window.GeometryPlans = [{"id":"P1-01","grade":1,"title":{"en":"Paths that bend and paths that go straight","pt":"Caminhos curvos e caminhos retos"},"gap":{"en":"Adds a spatial movement lesson before formal shape names.","pt":"Acrescenta uma vivência espacial antes dos nomes formais."},"source":"J192–193","ready":{"en":"Follow a short route and describe where it begins.","pt":"Seguir um percurso curto e indicar onde começa."},"materials":{"en":"Yarn, paper and broad crayons.","pt":"Fio de lã, papel e giz de cera grosso."},"aim":{"en":"Recognise straight and curved paths; distinguish an open path from a closed one.","pt":"Reconhecer caminhos retos e curvos; distinguir um caminho aberto de um fechado."},"teaching":{"en":"A straight path keeps one direction. A curved path changes direction. Either kind can be open; a closed boundary returns to its start and surrounds a region. Do not require degrees or formal definitions.","pt":"Um caminho reto mantém uma direção. Um caminho curvo muda de direção. Ambos podem ser abertos; um contorno fechado volta ao início e cerca uma região. Não exija graus nem definições formais."},"flow":[{"en":"5 min · Recall a walk to the door. Trace its route in the air.","pt":"5 min · Lembre um passeio até a porta. Trace o caminho no ar."},{"en":"10 min · Lay a straight yarn path and a curved one. Move a counter along each, then describe what changes.","pt":"10 min · Monte um caminho reto e outro curvo com lã. Mova uma ficha sobre cada um e descreva o que muda."},{"en":"10 min · Make an open curve, then close it. Draw both; place a counter inside and another outside the closed boundary.","pt":"10 min · Faça uma curva aberta e depois feche-a. Desenhe ambas; ponha uma ficha dentro e outra fora do contorno fechado."},{"en":"5 min · Show a new path and ask whether it closes. Recall the distinction tomorrow with a different shape.","pt":"5 min · Mostre um caminho novo e pergunte se fecha. Retome amanhã com outra forma."}],"practice":[{"q":{"en":"Does a straight segment return to its start?","pt":"Um segmento reto volta ao início?"},"a":{"en":"No; its two endpoints are different.","pt":"Não; suas duas extremidades são diferentes."}},{"q":{"en":"Can a curved path stay open?","pt":"Um caminho curvo pode ficar aberto?"},"a":{"en":"Yes, such as a U-shaped path. Curved does not mean closed.","pt":"Sim, como um caminho em U. Curvo não significa fechado."}},{"q":{"en":"Make a closed path with straight pieces.","pt":"Faça um caminho fechado com partes retas."},"a":{"en":"A triangle or rectangle works: the last piece meets the first.","pt":"Um triângulo ou retângulo serve: a última parte encontra a primeira."}}],"observe":{"en":"Ask the child to explain inside and outside using their own boundary.","pt":"Peça à criança para explicar dentro e fora usando seu contorno."},"support":{"en":"Move a toy or finger instead of walking; use a raised yarn boundary.","pt":"Mova um brinquedo ou dedo em vez de caminhar; use um contorno de lã em relevo."},"extend":{"en":"Combine straight and curved parts in one closed design.","pt":"Combine partes retas e curvas em um desenho fechado."},"links":["P2-01.html"],"diagram":"paths","duration":30},{"id":"P2-01","grade":2,"title":{"en":"A pattern across the fold","pt":"Um padrão do outro lado da dobra"},"gap":{"en":"Deepens early symmetry through matching distance and position.","pt":"Aprofunda a simetria inicial por distância e posição correspondentes."},"source":"J194","ready":{"en":"Distinguish two sides of a paper fold.","pt":"Distinguir os dois lados de uma dobra."},"materials":{"en":"Paper, washable paint or counters, crayons.","pt":"Papel, tinta lavável ou fichas, giz de cera."},"aim":{"en":"Create and check a reflected pattern without counting symmetry axes formally.","pt":"Criar e conferir um padrão refletido sem contar eixos formalmente."},"teaching":{"en":"A reflection pairs each point with one equally far from the fold on the opposite side. A point on the fold stays there. Matching colours alone does not make a reflection.","pt":"Uma reflexão associa cada ponto a outro igualmente distante da dobra, no lado oposto. Um ponto na dobra fica no mesmo lugar. Cores iguais, sozinhas, não garantem reflexão."},"flow":[{"en":"5 min · Fold and unfold paper; trace the crease.","pt":"5 min · Dobre e abra o papel; marque o vinco."},{"en":"10 min · Place three paint dots on one side and fold to print partners, or place counter pairs at matching distances.","pt":"10 min · Faça três pintas de tinta de um lado e dobre para imprimir seus pares, ou posicione pares de fichas a distâncias iguais."},{"en":"10 min · Draw a new pattern with one deliberate misplaced partner. Ask a friend to repair it by folding.","pt":"10 min · Desenhe um padrão com um par fora do lugar. Peça a alguém para corrigi-lo dobrando."},{"en":"5 min · Explain why a dot on the crease needs no second dot. Next day, repeat with a sloping fold.","pt":"5 min · Explique por que uma pinta no vinco não precisa de outra. No dia seguinte, repita com dobra inclinada."}],"practice":[{"q":{"en":"Three dots lie off the fold. How many partners are needed?","pt":"Três pintas estão fora da dobra. Quantos pares novos são necessários?"},"a":{"en":"Three new dots, giving six altogether.","pt":"Três pintas novas, totalizando seis."}},{"q":{"en":"A dot is two counter-widths from the fold. Where is its partner?","pt":"Uma pinta fica a duas larguras de ficha da dobra. Onde fica seu par?"},"a":{"en":"Opposite it, two counter-widths away on the other side.","pt":"Em frente, a duas larguras de ficha no outro lado."}},{"q":{"en":"Does tilting the paper destroy the reflection?","pt":"Inclinar o papel destrói a reflexão?"},"a":{"en":"No; the pairs still match when folded.","pt":"Não; os pares ainda coincidem ao dobrar."}}],"observe":{"en":"Check that the learner tests coincidence rather than guessing by colour.","pt":"Verifique se testa a coincidência em vez de adivinhar pela cor."},"support":{"en":"Use large tactile counter pairs; a partner may fold the paper.","pt":"Use pares grandes de fichas táteis; outra pessoa pode dobrar o papel."},"extend":{"en":"Place one dot on the fold and three off it: seven dots make the complete design.","pt":"Coloque uma pinta na dobra e três fora: sete pintas formam o desenho completo."},"links":["P3-01.html"],"diagram":"mirror","duration":30},{"id":"P3-01","grade":3,"title":{"en":"A plan of our reading corner","pt":"Uma planta do nosso canto de leitura"},"gap":{"en":"Connects practical measurement to position, plan views and scale.","pt":"Liga medidas práticas à posição, vista de cima e escala."},"source":"J194–195","ready":{"en":"Measure short lengths in centimetres and count equal groups.","pt":"Medir comprimentos curtos em centímetros e contar grupos iguais."},"materials":{"en":"Tape measure, squared paper and toy furniture.","pt":"Trena, papel quadriculado e móveis de brinquedo."},"aim":{"en":"Distinguish a top view from a front view; use a simple declared scale.","pt":"Distinguir vista de cima de vista frontal; usar uma escala simples declarada."},"teaching":{"en":"A plan looks down from above. Use 1 paper square for 10 cm in this model. A rectangular 60 cm by 40 cm tabletop becomes 6 by 4 squares. A drawing length and the real length need different unit labels.","pt":"Uma planta olha de cima. Use 1 quadradinho para 10 cm neste modelo. Uma mesa de 60 cm por 40 cm vira 6 por 4 quadradinhos. A medida do desenho e a real precisam de unidades distintas."},"flow":[{"en":"5 min · Look at a toy from above and from the side. Say which view shows its footprint.","pt":"5 min · Olhe um brinquedo de cima e de lado. Diga qual vista mostra o espaço que ocupa no chão."},{"en":"15 min · Measure a tabletop or use 60 cm by 40 cm. Build its 6 by 4 square plan and add a scale key.","pt":"15 min · Meça uma mesa ou use 60 cm por 40 cm. Faça uma planta de 6 por 4 quadradinhos e acrescente a legenda da escala."},{"en":"5 min · Put a 20 cm square cushion on the model. Draw its 2 by 2 square footprint in two possible positions.","pt":"5 min · Ponha uma almofada quadrada de 20 cm no modelo. Desenhe sua marca de 2 por 2 quadradinhos em duas posições."},{"en":"5 min · Explain how to recover one real length from the plan; revisit the scale next week.","pt":"5 min · Explique como recuperar uma medida real pela planta; retome a escala na próxima semana."}],"practice":[{"q":{"en":"Draw a 30 cm shelf at this scale.","pt":"Desenhe uma prateleira de 30 cm nessa escala."},"a":{"en":"Three squares long, since 3 × 10 = 30 cm.","pt":"Três quadradinhos de comprimento, pois 3 × 10 = 30 cm."}},{"q":{"en":"A side is 5 squares. What real length is it?","pt":"Um lado mede 5 quadradinhos. Qual é a medida real?"},"a":{"en":"50 cm; multiply the square count by 10 cm.","pt":"50 cm; multiplique a quantidade de quadradinhos por 10 cm."}},{"q":{"en":"Can a 50 cm by 30 cm mat fit on the model tabletop?","pt":"Um tapete de 50 cm por 30 cm cabe na mesa do modelo?"},"a":{"en":"Yes: a 5 by 3 square footprint fits within 6 by 4, with sides aligned.","pt":"Sim: 5 por 3 quadradinhos cabem em 6 por 4, com lados alinhados."}}],"observe":{"en":"Ask for the viewpoint, scale key and units before accepting a neat drawing.","pt":"Peça a vista, a legenda da escala e as unidades antes de aceitar um desenho caprichado."},"support":{"en":"Provide a prepared grid and lengths; use cut-out furniture.","pt":"Forneça grade e medidas prontas; use móveis recortados."},"extend":{"en":"Compare two arrangements and describe a route between the furniture.","pt":"Compare duas disposições e descreva um caminho entre os móveis."},"links":["../lessons/G6-15.html"],"diagram":"plan","duration":30},{"id":"P4-01","grade":4,"title":{"en":"From a round walk to an ellipse","pt":"Do passeio circular à elipse"},"gap":{"en":"Adds the missing movement-to-drawing comparison of circle and ellipse.","pt":"Acrescenta a comparação entre movimento e desenho de círculo e elipse."},"source":"S14–22","ready":{"en":"Recognise an open and a closed path; follow a boundary with a finger.","pt":"Reconhecer caminhos abertos e fechados; seguir um contorno com o dedo."},"materials":{"en":"Yarn, paper, crayons and prepared circle/ellipse outlines.","pt":"Lã, papel, giz de cera e contornos preparados de círculo e elipse."},"aim":{"en":"Compare a circle and an ellipse through direction changes and symmetry.","pt":"Comparar círculo e elipse por mudanças de direção e simetria."},"teaching":{"en":"A circle keeps a constant distance from one centre. A noncircular ellipse is longer along one axis than the other; its tighter turns occur near the ends of the long axis. An oval-looking freehand drawing is a sketch, not automatically an exact ellipse.","pt":"O círculo mantém distância constante de um centro. Uma elipse não circular é mais comprida em um eixo do que no outro; as curvas mais fechadas ficam nas pontas do eixo maior. Um desenho oval à mão livre é um esboço, não automaticamente uma elipse exata."},"flow":[{"en":"5 min · Recall straight and curved paths. Move a toy around a circular yarn loop once.","pt":"5 min · Retome caminhos retos e curvos. Mova um brinquedo uma vez pelo círculo de lã."},{"en":"15 min · Reshape the loop into a long oval. Compare where the toy changes direction slowly and where it turns more tightly. Draw the two paths freehand.","pt":"15 min · Transforme o laço em oval comprido. Compare onde a direção muda suavemente e onde a curva fica mais fechada. Desenhe os dois caminhos à mão livre."},{"en":"20 min · Use prepared mathematical circle and ellipse outlines. Fold across their centres to test matching halves. Mark the ellipse’s two axes and compare centre-to-boundary lengths.","pt":"20 min · Use contornos matemáticos preparados de círculo e elipse. Dobre pelo centro para testar metades coincidentes. Marque os dois eixos da elipse e compare distâncias do centro ao contorno."},{"en":"5 min · Describe one similarity and one difference; repeat from memory tomorrow.","pt":"5 min · Descreva uma semelhança e uma diferença; repita de memória amanhã."}],"practice":[{"q":{"en":"An ellipse has full axis lengths 12 cm and 8 cm. What are the half-axis lengths?","pt":"Uma elipse tem eixos completos de 12 cm e 8 cm. Quais são os semieixos?"},"a":{"en":"6 cm and 4 cm: halve each full length.","pt":"6 cm e 4 cm: tome a metade de cada comprimento."}},{"q":{"en":"Do all centre-to-boundary lengths match on this ellipse?","pt":"Todas as distâncias do centro ao contorno coincidem nessa elipse?"},"a":{"en":"No: 6 cm and 4 cm already give different lengths.","pt":"Não: 6 cm e 4 cm já dão comprimentos diferentes."}},{"q":{"en":"How many reflection axes does a noncircular ellipse have?","pt":"Quantos eixos de reflexão tem uma elipse não circular?"},"a":{"en":"Two, its major and minor axes. A circle has infinitely many.","pt":"Dois: o maior e o menor. Um círculo tem infinitos."}}],"observe":{"en":"Look for an explanation connecting the path, the drawing and the change of direction.","pt":"Observe uma explicação ligando percurso, desenho e mudança de direção."},"support":{"en":"Use seated finger or toy movement; use prepared outlines for fold tests.","pt":"Use movimento sentado com dedo ou brinquedo; use contornos prontos para dobrar."},"extend":{"en":"Compare a circle as the equal-axis special case, without requiring ellipse formulas.","pt":"Compare o círculo como caso de eixos iguais, sem exigir fórmulas de elipse."},"links":["P1-01.html","../lessons/G5-01.html"],"diagram":"ellipse","duration":45,"jarman":"73–75,195"},{"id":"P4-02","grade":4,"title":{"en":"Triangles that change and stay triangles","pt":"Triângulos que mudam e continuam triângulos"},"gap":{"en":"Adds systematic freehand triangle variation before construction criteria.","pt":"Acrescenta variações de triângulos à mão livre antes dos critérios de construção."},"source":"S23–26","ready":{"en":"Count sides and corners; compare lengths by superposition.","pt":"Contar lados e vértices; comparar comprimentos por sobreposição."},"materials":{"en":"Three strips, paper, crayons and a folded right-angle corner.","pt":"Três tiras, papel, giz de cera e um canto reto dobrado."},"aim":{"en":"Keep the three-sided boundary while changing size, orientation and side relationships.","pt":"Manter o contorno de três lados mudando tamanho, orientação e relações entre lados."},"teaching":{"en":"A triangle has three straight sides enclosing a region. Rotating it changes neither side lengths nor angle types. Equilateral means all three sides equal; isosceles here means at least two equal, so an equilateral triangle also belongs.","pt":"Um triângulo tem três lados retos cercando uma região. Girá-lo não altera comprimentos nem tipos de ângulo. Equilátero tem três lados iguais; isósceles aqui tem pelo menos dois iguais, então inclui o equilátero."},"flow":[{"en":"5 min · Draw a triangle standing on a side, then turn the paper. Ask whether its name changes.","pt":"5 min · Desenhe um triângulo apoiado num lado e gire o papel. Pergunte se seu nome muda."},{"en":"15 min · Sketch three equal-sided triangles of increasing size. Compare side relationships rather than drawing neatness.","pt":"15 min · Esboce três triângulos equiláteros de tamanhos crescentes. Compare relações entre lados, sem avaliar o capricho."},{"en":"20 min · Hold a base fixed and move the top vertex to three positions. Make one symmetric and one right-angled example. Compare with strips and a folded corner.","pt":"20 min · Mantenha uma base fixa e mova o vértice superior para três posições. Faça um exemplo simétrico e um retângulo. Compare com tiras e um canto dobrado."},{"en":"5 min · Sort the sketches using one stated property; recall it tomorrow on a rotated triangle.","pt":"5 min · Separe os desenhos por uma propriedade declarada; retome amanhã com triângulo girado."}],"practice":[{"q":{"en":"Does a rotated equilateral triangle still have equal sides?","pt":"Um triângulo equilátero girado continua com lados iguais?"},"a":{"en":"Yes; rotation preserves all lengths.","pt":"Sim; a rotação preserva todos os comprimentos."}},{"q":{"en":"A triangle has sides 5, 5 and 6 cm. Is it equilateral?","pt":"Um triângulo tem lados 5, 5 e 6 cm. É equilátero?"},"a":{"en":"No; it is isosceles with two equal sides.","pt":"Não; é isósceles com dois lados iguais."}},{"q":{"en":"Can three points on one straight line make a triangle?","pt":"Três pontos na mesma reta formam um triângulo?"},"a":{"en":"No; the segments enclose no region.","pt":"Não; os segmentos não cercam uma região."}}],"observe":{"en":"Ask what stayed unchanged when the vertex moved; check that a rotated shape is recognised.","pt":"Pergunte o que permaneceu quando o vértice mudou; verifique o reconhecimento da forma girada."},"support":{"en":"Use large pre-cut triangles and compare by touch or tracing.","pt":"Use triângulos grandes recortados e compare pelo tato ou contorno."},"extend":{"en":"Hold base and perpendicular height fixed while shifting the vertex; save the area question for later.","pt":"Mantenha base e altura perpendicular fixas ao mover o vértice; guarde a questão da área para depois."},"links":["../lessons/G5-03.html","../lessons/G6-10.html"],"diagram":"triangles","duration":45,"jarman":"73–75,195"},{"id":"P4-03","grade":4,"title":{"en":"The quadrilateral workshop","pt":"A oficina dos quadriláteros"},"gap":{"en":"Replaces a brief shape-family mention with explicit inclusive classification and symmetry tests.","pt":"Amplia a menção às famílias de formas com classificação inclusiva e testes de simetria."},"source":"S27–38","ready":{"en":"Recognise four straight sides and test a right angle.","pt":"Reconhecer quatro lados retos e testar um ângulo reto."},"materials":{"en":"Paper quadrilaterals, tracing paper and folded right-angle corner.","pt":"Quadriláteros de papel, papel vegetal e canto reto dobrado."},"aim":{"en":"Classify squares, rectangles, rhombi and parallelograms by properties, including overlapping memberships.","pt":"Classificar quadrados, retângulos, losangos e paralelogramos por propriedades, incluindo grupos que se sobrepõem."},"teaching":{"en":"A rectangle has four right angles; a rhombus has four equal sides; a parallelogram has two pairs of opposite parallel sides. A square satisfies all three definitions. A nonsquare rectangle has two reflection axes, a nonsquare rhombus two, and a square four. A generic slanted parallelogram has no reflection axis but matches after a half-turn.","pt":"Um retângulo tem quatro ângulos retos; um losango tem quatro lados iguais; um paralelogramo tem dois pares de lados opostos paralelos. Um quadrado satisfaz as três definições. Um retângulo não quadrado tem dois eixos de reflexão, um losango não quadrado dois, e um quadrado quatro. Um paralelogramo inclinado genérico não tem eixo de reflexão, mas coincide após meia-volta."},"flow":[{"en":"5 min · Recall a square’s four sides and four right angles.","pt":"5 min · Retome os quatro lados e quatro ângulos retos do quadrado."},{"en":"15 min · Sort prepared shapes under four property cards. Allow one shape to appear under several cards by tracing copies.","pt":"15 min · Separe formas com quatro cartões de propriedades. Permita que uma forma entre em vários grupos usando cópias traçadas."},{"en":"20 min · Fold copies of a square, nonsquare rectangle and nonsquare rhombus. Test diagonals and lines through side midpoints; turn a generic parallelogram halfway using tracing paper.","pt":"20 min · Dobre cópias de quadrado, retângulo não quadrado e losango não quadrado. Teste diagonais e linhas pelos pontos médios; gire um paralelogramo genérico meia-volta com papel vegetal."},{"en":"5 min · Explain why a square belongs in the rectangle group. Revisit with a tilted square next week.","pt":"5 min · Explique por que o quadrado pertence ao grupo dos retângulos. Retome com um quadrado inclinado na próxima semana."}],"practice":[{"q":{"en":"Is every square a rectangle?","pt":"Todo quadrado é retângulo?"},"a":{"en":"Yes, because it has four right angles.","pt":"Sim, pois tem quatro ângulos retos."}},{"q":{"en":"Is a 3 cm by 5 cm rectangle a rhombus?","pt":"Um retângulo de 3 cm por 5 cm é losango?"},"a":{"en":"No: its four sides are not all equal.","pt":"Não: seus quatro lados não são todos iguais."}},{"q":{"en":"Does a half-turn prove reflection symmetry?","pt":"Meia-volta demonstra simetria de reflexão?"},"a":{"en":"No. Rotation and reflection are different movements; test a fold separately.","pt":"Não. Rotação e reflexão são movimentos distintos; teste a dobra separadamente."}}],"observe":{"en":"Require a property-based reason, including an example that belongs to more than one family.","pt":"Exija uma justificativa por propriedades, incluindo um exemplo que pertence a mais de uma família."},"support":{"en":"Use prepared shapes; read property cards aloud and test by overlay.","pt":"Use formas prontas; leia os cartões em voz alta e teste por sobreposição."},"extend":{"en":"Compare a kite and an isosceles trapezoid. State whether trapezoid means exactly one or at least one parallel pair before classifying.","pt":"Compare deltoide e trapézio isósceles. Declare se trapézio significa exatamente um ou pelo menos um par de paralelas antes de classificar."},"links":["P4-02.html","../lessons/G5-03.html"],"diagram":"quads","duration":45,"jarman":"151–152,197"},{"id":"P4-04","grade":4,"title":{"en":"A round ball, a changing shadow","pt":"Uma bola redonda, uma sombra que muda"},"gap":{"en":"Adds the book’s missing spatial light-and-shadow investigation.","pt":"Acrescenta a investigação espacial de luz e sombra que faltava."},"source":"S39–42","ready":{"en":"Distinguish a solid object from its flat outline; recall circle and ellipse.","pt":"Distinguir sólido de contorno plano; retomar círculo e elipse."},"materials":{"en":"Ball, stable LED torch, white card and pencil.","pt":"Bola, lanterna LED estável, cartolina branca e lápis."},"aim":{"en":"Distinguish a sphere from a disk and compare shadows when the receiving surface tilts.","pt":"Distinguir esfera de disco e comparar sombras quando a superfície receptora inclina."},"teaching":{"en":"A sphere is a three-dimensional surface; its shadow is a two-dimensional region on a receiving surface. With near-parallel light, a plane perpendicular to the beam gives a circular shadow; tilting the plane can give an elongated ellipse. A nearby torch has diverging rays: describe actual observations rather than promising an exact ellipse.","pt":"A esfera é uma superfície tridimensional; sua sombra é uma região bidimensional numa superfície receptora. Com luz quase paralela, um plano perpendicular ao feixe dá sombra circular; inclinar o plano pode dar uma elipse alongada. Uma lanterna próxima tem raios divergentes: descreva observações reais em vez de prometer elipse exata."},"flow":[{"en":"5 min · Compare a paper disk with a ball from several directions.","pt":"5 min · Compare um disco de papel com uma bola de várias direções."},{"en":"15 min · An adult positions an LED torch and ball securely. Hold the receiving card across the beam and trace the shadow. Keep the ball and light fixed.","pt":"15 min · Um adulto posiciona lanterna LED e bola com estabilidade. Segure a cartolina atravessando o feixe e trace a sombra. Mantenha bola e luz fixas."},{"en":"20 min · Tilt only the card, tracing three outlines. Record exactly what moved. Never shine light into eyes; use supplied descriptions if equipment is unavailable.","pt":"20 min · Incline apenas a cartolina e trace três contornos. Registre exatamente o que mudou. Não aponte luz para os olhos; use as descrições fornecidas se não houver equipamento."},{"en":"5 min · Explain how a round object can cast a stretched shadow. Compare the drawings again tomorrow.","pt":"5 min · Explique como um objeto redondo projeta sombra alongada. Compare os desenhos novamente amanhã."}],"practice":[{"q":{"en":"Did tilting the card change the ball’s shape?","pt":"Inclinar a cartolina mudou a forma da bola?"},"a":{"en":"No. The receiving surface changed orientation.","pt":"Não. A superfície receptora mudou de orientação."}},{"q":{"en":"Is the shadow a sphere?","pt":"A sombra é uma esfera?"},"a":{"en":"No: it is a flat region, not the three-dimensional object.","pt":"Não: é uma região plana, não o objeto tridimensional."}},{"q":{"en":"Two trials move both card and lamp. Can the difference be attributed only to card tilt?","pt":"Dois testes movem cartolina e lanterna. A diferença pode ser atribuída só à inclinação?"},"a":{"en":"No; change one condition at a time to make that comparison.","pt":"Não; mude uma condição por vez para fazer essa comparação."}}],"observe":{"en":"Listen for the distinction between object, light and receiving plane.","pt":"Observe a distinção entre objeto, luz e plano receptor."},"support":{"en":"Compare a prepared circular outline and elongated outline while someone describes the experiment.","pt":"Compare um contorno circular e outro alongado enquanto alguém descreve o experimento."},"extend":{"en":"Compare shadows cast by a disk and a ball; explain the role of orientation.","pt":"Compare sombras de disco e bola; explique o papel da orientação."},"links":["P4-01.html","../lessons/G6-12.html"],"diagram":"shadow","duration":45},{"id":"P5-01","grade":5,"title":{"en":"Two circles reveal a midpoint","pt":"Duas circunferências revelam um ponto médio"},"gap":{"en":"Connects observed symmetry to the perpendicular-bisector construction.","pt":"Liga a simetria observada à construção da mediatriz."},"source":"S50–53,64–69","ready":{"en":"Fold a reflection axis; keep a compass opening unchanged.","pt":"Dobrar um eixo de reflexão; manter a abertura do compasso."},"materials":{"en":"Paper, compass, ruler and tracing paper.","pt":"Papel, compasso, régua e papel vegetal."},"aim":{"en":"Use equal-radius circles to find a midpoint and explain their two reflection axes.","pt":"Usar circunferências de raios iguais para encontrar um ponto médio e explicar seus dois eixos de reflexão."},"teaching":{"en":"For distinct centres A and B, two equal-radius circles share reflection in line AB and in its perpendicular bisector. If the radius exceeds half AB, the two intersections C and D determine that bisector: each lies equally far from A and B. Joining C and D meets AB at its midpoint M. If the radius is too small, the circles do not intersect.","pt":"Para centros distintos A e B, duas circunferências de raios iguais têm reflexão na reta AB e em sua mediatriz. Se o raio é maior que metade de AB, as interseções C e D determinam a mediatriz: cada uma fica à mesma distância de A e B. CD encontra AB no ponto médio M. Se o raio é pequeno demais, as circunferências não se encontram."},"flow":[{"en":"5 min · Recall a fold that swaps two marked points.","pt":"5 min · Retome uma dobra que troca dois pontos marcados."},{"en":"15 min · Mark A and B 6 cm apart. With radius 4 cm draw both circles. Name their intersections C and D, then join CD and mark M on AB. Keep working arcs.","pt":"15 min · Marque A e B a 6 cm. Com raio de 4 cm, trace ambas as circunferências. Nomeie as interseções C e D, una CD e marque M em AB. Preserve os arcos."},{"en":"20 min · Fold on AB and CD to test the whole pair of circles. Measure AM and MB only after predicting equality. Repeat with the same centres and radius 5 cm.","pt":"20 min · Dobre em AB e CD para testar o par completo de circunferências. Meça AM e MB só depois de prever a igualdade. Repita com os mesmos centros e raio de 5 cm."},{"en":"5 min · Explain what changed and why the midpoint did not; repeat with new centres next week.","pt":"5 min · Explique o que mudou e por que o ponto médio não mudou; repita com novos centros na próxima semana."}],"practice":[{"q":{"en":"Find AM when AB is 6 cm.","pt":"Encontre AM quando AB mede 6 cm."},"a":{"en":"3 cm, because M divides AB into two equal parts.","pt":"3 cm, pois M divide AB em duas partes iguais."}},{"q":{"en":"Will two radius-2 cm circles with centres 6 cm apart intersect?","pt":"Duas circunferências de raio 2 cm com centros separados por 6 cm se encontram?"},"a":{"en":"No: 2 + 2 < 6. There is no C or D to join.","pt":"Não: 2 + 2 < 6. Não há C nem D para unir."}},{"q":{"en":"Why is C equally distant from A and B?","pt":"Por que C fica igualmente distante de A e B?"},"a":{"en":"CA and CB are radii of circles drawn with the same opening.","pt":"CA e CB são raios de circunferências traçadas com a mesma abertura."}}],"observe":{"en":"Check the unchanged compass opening, two intersections and an equality explanation.","pt":"Confira abertura constante, duas interseções e explicação da igualdade."},"support":{"en":"Use prepared intersecting circles and trace the two axes. Ask an adult to handle a sharp compass.","pt":"Use circunferências prontas e trace os eixos. Peça a um adulto para manusear o compasso pontiagudo."},"extend":{"en":"Compare unequal-radius circles: AB remains an axis but the perpendicular bisector generally does not.","pt":"Compare raios diferentes: AB continua eixo, mas a mediatriz em geral não."},"links":["../lessons/G6-02.html","../lessons/G6-06.html"],"diagram":"bisector","duration":45,"jarman":"94,102–103"},{"id":"P5-02","grade":5,"title":{"en":"From four corners to eight","pt":"De quatro vértices a oito"},"gap":{"en":"Adds a readiness-based Grade 5 square-to-octagon construction bridge.","pt":"Acrescenta uma ponte de construção do quadrado ao octógono no 5º ano, conforme a prontidão."},"source":"S68–75","ready":{"en":"Use midpoint and angle-bisector constructions; otherwise begin with the linked Grade 6 lessons.","pt":"Usar construções de ponto médio e bissetriz; caso contrário, começar pelas aulas do 6º ano vinculadas."},"materials":{"en":"Paper, compass, straightedge and ruler for checking.","pt":"Papel, compasso, régua sem graduação e régua graduada para conferir."},"aim":{"en":"Construct a square and regular octagon in one circle; connect equal central gaps with equal sides.","pt":"Construir quadrado e octógono regular na mesma circunferência; ligar intervalos centrais iguais a lados iguais."},"teaching":{"en":"Two perpendicular diameters divide a circle into four equal 90° sectors. Their endpoints form a square. Bisecting each central angle creates eight equal 45° sectors, whose endpoints form a regular octagon. Equal gaps, not equal-looking marks, justify equal chords. A chord midpoint is inside the circle and is not a new octagon vertex.","pt":"Dois diâmetros perpendiculares dividem a circunferência em quatro setores de 90°. As extremidades formam um quadrado. Bissetar cada ângulo central cria oito setores de 45°, cujas extremidades formam um octógono regular. Intervalos iguais, não marcas parecidas, justificam cordas iguais. O ponto médio de uma corda fica dentro do círculo e não é um novo vértice do octógono."},"flow":[{"en":"5 min · Recall four quarter-turns and an equal-radius construction.","pt":"5 min · Retome quatro quartos de volta e uma construção com raios iguais."},{"en":"15 min · Draw a circle centred at O and a diameter AB. Construct its perpendicular bisector through O; mark its two intersections with the circle. Join the four boundary points in order.","pt":"15 min · Trace circunferência de centro O e diâmetro AB. Construa a mediatriz de AB passando por O; marque suas duas interseções com a circunferência. Una os quatro pontos do contorno em ordem."},{"en":"20 min · Bisect each 90° central angle: an arc centred at O marks equal distances on its rays; equal arcs from those marks meet inside the angle; join O to that intersection. Extend to the original circle. Join all eight boundary points in order.","pt":"20 min · Bissete cada ângulo central de 90°: um arco de centro O marca distâncias iguais nas semirretas; arcos iguais dessas marcas se encontram dentro do ângulo; una O à interseção. Prolongue até a circunferência original. Una os oito pontos do contorno em ordem."},{"en":"5 min · Compare side lengths as a check, then explain the equal-angle reason. Reconstruct one bisector tomorrow.","pt":"5 min · Compare os lados para conferir e explique a razão dos ângulos iguais. Reconstrua uma bissetriz amanhã."}],"practice":[{"q":{"en":"What is each octagon central angle?","pt":"Quanto mede cada ângulo central do octógono?"},"a":{"en":"360° ÷ 8 = 45°.","pt":"360° ÷ 8 = 45°."}},{"q":{"en":"Is a square-side midpoint on its circumcircle?","pt":"O ponto médio de um lado do quadrado está na circunferência circunscrita?"},"a":{"en":"No; extend the ray from the centre through it to the circle.","pt":"Não; prolongue a semirreta do centro por ele até a circunferência."}},{"q":{"en":"What regular polygon results from bisecting all eight gaps again?","pt":"Qual polígono regular resulta ao bissetar novamente os oito intervalos?"},"a":{"en":"A 16-sided polygon with central angles 22.5°.","pt":"Um polígono de 16 lados com ângulos centrais de 22,5°."}}],"observe":{"en":"Look for boundary vertices and retained construction arcs; do not infer accuracy from decoration.","pt":"Observe vértices no contorno e arcos preservados; não deduza precisão pela decoração."},"support":{"en":"Provide the square and work on one bisector; use the existing step-by-step bisector lesson.","pt":"Forneça o quadrado e trabalhe uma bissetriz; use a aula de bissetriz passo a passo."},"extend":{"en":"Add alternate-vertex connections and state which polygon they form.","pt":"Ligue vértices alternados e diga qual polígono formam."},"links":["P5-01.html","../lessons/G6-08.html","../lessons/G6-09.html"],"diagram":"octagon","duration":45,"jarman":"94,102–103"},{"id":"P5-03","grade":5,"title":{"en":"Squares nested by their midpoints","pt":"Quadrados encaixados pelos pontos médios"},"gap":{"en":"Adds a geometric art sequence with an explicit area relationship.","pt":"Acrescenta uma sequência de arte geométrica com relação explícita de áreas."},"source":"S54–56,68–69","ready":{"en":"Identify a midpoint and count square units.","pt":"Identificar ponto médio e contar unidades quadradas."},"materials":{"en":"Squared paper, ruler, compass or folded midpoint marks, crayons.","pt":"Papel quadriculado, régua, compasso ou pontos médios por dobra, giz de cera."},"aim":{"en":"Connect side midpoints to form a new square and compare successive areas.","pt":"Ligar pontos médios para formar outro quadrado e comparar áreas sucessivas."},"teaching":{"en":"In an 8 cm square, joining side midpoints removes four corner right triangles, each with legs 4 cm and area 8 cm². The inner square has area 64 − 32 = 32 cm². Its tilted position does not change its being a square. Each repeated midpoint square halves the area, not the side length.","pt":"Num quadrado de 8 cm, unir pontos médios remove quatro triângulos retângulos, cada um com catetos de 4 cm e área de 8 cm². O quadrado interno tem área 64 − 32 = 32 cm². A inclinação não deixa de torná-lo quadrado. Cada novo quadrado de pontos médios reduz a área à metade, não o lado."},"flow":[{"en":"5 min · Recall the area of an 8 by 8 square and the meaning of midpoint.","pt":"5 min · Retome a área de um quadrado de 8 por 8 e o significado de ponto médio."},{"en":"15 min · Draw the outer square; find four side midpoints by fold, construction or grid count. Join them in cyclic order. Test equal sides and right angles.","pt":"15 min · Desenhe o quadrado externo; encontre quatro pontos médios por dobra, construção ou contagem. Una-os em ordem. Teste lados iguais e ângulos retos."},{"en":"20 min · Cut or trace four corner triangles. Pair them into two 4 by 4 squares to compare removed and remaining area. Repeat the midpoint step twice and record areas.","pt":"20 min · Recorte ou trace os quatro triângulos dos cantos. Junte-os em dois quadrados de 4 por 4 para comparar área removida e restante. Repita o passo dos pontos médios duas vezes e registre áreas."},{"en":"5 min · Explain why area halves. Next week, predict before drawing in a different-sized square.","pt":"5 min · Explique por que a área cai à metade. Na próxima semana, preveja antes de desenhar em outro quadrado."}],"practice":[{"q":{"en":"Give the first three inner areas when the outer area is 64 cm².","pt":"Dê as três primeiras áreas internas quando a externa é 64 cm²."},"a":{"en":"32, 16 and 8 cm²; halve each previous area.","pt":"32, 16 e 8 cm²; tome metade da área anterior."}},{"q":{"en":"Would halving an 8 cm side produce half the area?","pt":"Reduzir um lado de 8 cm à metade produz metade da área?"},"a":{"en":"No: a 4 cm square has 16 cm², one quarter of 64 cm².","pt":"Não: um quadrado de 4 cm tem 16 cm², um quarto de 64 cm²."}},{"q":{"en":"An outer square has area 100 cm². Predict its first midpoint-square area.","pt":"Um quadrado externo tem área de 100 cm². Preveja a área do primeiro quadrado dos pontos médios."},"a":{"en":"50 cm² by the same four-corner rearrangement.","pt":"50 cm² pelo mesmo rearranjo dos quatro cantos."}}],"observe":{"en":"Ask for a cut-and-match reason and distinguish side scale from area scale.","pt":"Peça justificativa por recorte e distinga escala de lado da de área."},"support":{"en":"Use a prepared grid and pre-cut triangles; postpone formulas until the pieces match.","pt":"Use grade pronta e triângulos recortados; adie fórmulas até as peças coincidirem."},"extend":{"en":"Compare perimeters: each new side is the old side divided by √2; treat this as optional later work.","pt":"Compare perímetros: cada lado novo é o anterior dividido por √2; trate como extensão posterior opcional."},"links":["P4-03.html","../lessons/G7-06.html"],"diagram":"nested","duration":45,"jarman":"171–172"},{"id":"P5-04","grade":5,"title":{"en":"Double a square without doubling its side","pt":"Dobre a área do quadrado sem dobrar o lado"},"gap":{"en":"Adds an experiential diagonal-square bridge before the general Pythagorean theorem.","pt":"Acrescenta uma ponte vivencial pelo quadrado da diagonal antes do teorema geral de Pitágoras."},"source":"S82–84","ready":{"en":"Count square units; identify a square and a diagonal.","pt":"Contar unidades quadradas; identificar quadrado e diagonal."},"materials":{"en":"Grid paper, four congruent right-isosceles triangles, tape.","pt":"Papel quadriculado, quatro triângulos retângulos isósceles congruentes, fita."},"aim":{"en":"Build a square on a diagonal and justify its doubled area using equal pieces.","pt":"Construir um quadrado sobre uma diagonal e justificar o dobro da área com peças iguais."},"teaching":{"en":"Cut two 4 cm squares along one diagonal each. The four equal right-isosceles triangles each have area 8 cm². Place their right-angle vertices together at one centre; their hypotenuses bound a larger square. Its area is 4 × 8 = 32 cm², twice 16 cm². This special case prepares for a later general theorem; it is not a proof for every right triangle.","pt":"Corte dois quadrados de 4 cm por uma diagonal cada. Os quatro triângulos retângulos isósceles têm área de 8 cm² cada. Junte seus vértices de ângulo reto num centro; as hipotenusas delimitam um quadrado maior. Sua área é 4 × 8 = 32 cm², o dobro de 16 cm². Esse caso prepara um teorema geral posterior; não demonstra todos os triângulos retângulos."},"flow":[{"en":"5 min · Predict how to make a square of twice the area. Record the tempting doubled-side guess.","pt":"5 min · Preveja como fazer um quadrado com o dobro da área. Registre a hipótese de dobrar o lado."},{"en":"15 min · Make two 4 by 4 squares and cut along one diagonal in each. Label the four equal pieces and compare their areas.","pt":"15 min · Faça dois quadrados de 4 por 4 e corte uma diagonal de cada. Identifique as quatro peças iguais e compare suas áreas."},{"en":"20 min · Arrange the four right-angle corners around one centre, with 4 cm legs touching. Check no gap or overlap. Trace the outside square and compare with one original square and an 8 by 8 square.","pt":"20 min · Junte os quatro ângulos retos num centro, com catetos de 4 cm encostados. Confira ausência de lacunas ou sobreposição. Trace o quadrado externo e compare com um original e um de 8 por 8."},{"en":"5 min · Explain why doubling the side fails; repeat the reasoning next week with a 3 cm square.","pt":"5 min · Explique por que dobrar o lado não funciona; repita o raciocínio na próxima semana com um quadrado de 3 cm."}],"practice":[{"q":{"en":"What area doubles 16 cm²?","pt":"Qual área é o dobro de 16 cm²?"},"a":{"en":"32 cm²; four triangles of 8 cm² fill it.","pt":"32 cm²; quatro triângulos de 8 cm² a preenchem."}},{"q":{"en":"What area has a square with side 8 cm?","pt":"Qual é a área de um quadrado de lado 8 cm?"},"a":{"en":"64 cm², four times the 4 cm square’s area.","pt":"64 cm², quatro vezes a área do quadrado de 4 cm."}},{"q":{"en":"A square has side 3 cm. What is the area of the square on its diagonal?","pt":"Um quadrado tem lado 3 cm. Qual é a área do quadrado sobre sua diagonal?"},"a":{"en":"18 cm²: twice 3 × 3 = 9 cm².","pt":"18 cm²: o dobro de 3 × 3 = 9 cm²."}}],"observe":{"en":"Check conservation of the four pieces and a spoken comparison of areas.","pt":"Confira conservação das quatro peças e comparação oral das áreas."},"support":{"en":"Provide pre-cut pieces; let the learner direct a partner’s arrangement.","pt":"Forneça peças recortadas; deixe o estudante orientar a montagem de outra pessoa."},"extend":{"en":"Later, connect the side length 4√2 cm with 4² + 4²; keep the area experience first.","pt":"Depois, ligue o lado de 4√2 cm a 4² + 4²; mantenha primeiro a experiência de áreas."},"links":["P5-03.html","../lessons/G7-08.html","../lessons/G7-09.html"],"diagram":"double","duration":45,"jarman":"92–94"},{"id":"P6-01","grade":6,"title":{"en":"Copy an angle and explain a parallel","pt":"Copie um ângulo e explique uma paralela"},"gap":{"en":"Deepens parallel construction with an explicit angle-transfer procedure.","pt":"Aprofunda a construção de paralelas com procedimento explícito de transferência de ângulo."},"source":"S77–79","ready":{"en":"Use a compass to transfer distances; name angle vertices and rays.","pt":"Usar compasso para transferir distâncias; nomear vértices e semirretas."},"materials":{"en":"Compass, straightedge, paper and protractor for checking.","pt":"Compasso, régua sem graduação, papel e transferidor para conferir."},"aim":{"en":"Copy an angle by transferring an arc radius and chord; explain how corresponding angles construct a parallel.","pt":"Copiar um ângulo transferindo raio de arco e corda; explicar como ângulos correspondentes constroem uma paralela."},"teaching":{"en":"To copy ∠AOB at P on a chosen ray, draw equal-radius arcs centred at O and P. The first arc meets OA and OB at U and V; the second meets the given ray at U′. Copy chord UV with centre U′ to meet the second arc at V′. Ray PV′ completes an equal angle: triangles OUV and PU′V′ have three matching sides. Choose the intended side of the ray.","pt":"Para copiar ∠AOB em P numa semirreta escolhida, trace arcos de raios iguais com centros O e P. O primeiro encontra OA e OB em U e V; o segundo encontra a semirreta em U′. Copie a corda UV com centro U′ para encontrar o segundo arco em V′. PV′ completa ângulo igual: os triângulos OUV e PU′V′ têm três lados correspondentes iguais. Escolha o lado pretendido da semirreta."},"flow":[{"en":"5 min · Recall how a compass transfers length and why a protractor checks rather than constructs an exact copy.","pt":"5 min · Retome a transferência de comprimento e por que o transferidor confere, em vez de construir, uma cópia exata."},{"en":"15 min · Draw any acute angle and copy it at P using the two arcs and chord. Label O,U,V,P,U′,V′. Measure both angles afterwards.","pt":"15 min · Desenhe um ângulo agudo e copie-o em P com dois arcos e uma corda. Identifique O,U,V,P,U′,V′. Meça ambos depois."},{"en":"20 min · Draw line l, point P off it and Q on l. Extend QP beyond P. Copy at P the angle between the ray QP and a ray along l, using the ray beyond P as the new starting ray. Choose the matching corresponding-angle side; extend the new ray into a line.","pt":"20 min · Trace reta l, ponto P fora dela e Q em l. Prolongue QP além de P. Copie em P o ângulo entre QP e uma semirreta de l, usando a semirreta além de P como origem da cópia. Escolha o lado do ângulo correspondente; prolongue a nova semirreta em reta."},{"en":"5 min · Explain why equal corresponding angles imply parallel lines. Repeat with an obtuse angle next week.","pt":"5 min · Explique por que ângulos correspondentes iguais implicam paralelas. Repita com um ângulo obtuso na próxima semana."}],"practice":[{"q":{"en":"What two compass distances must be copied?","pt":"Quais duas distâncias do compasso devem ser copiadas?"},"a":{"en":"The arc radius and the chord between the angle rays.","pt":"O raio do arco e a corda entre as semirretas do ângulo."}},{"q":{"en":"If the original angle is 58°, what should its copy measure?","pt":"Se o ângulo original mede 58°, quanto deve medir a cópia?"},"a":{"en":"58°; drawing error can affect the measured check.","pt":"58°; erros de desenho podem afetar a conferência."}},{"q":{"en":"Is equal-looking slope sufficient justification?","pt":"Inclinação aparentemente igual basta como justificativa?"},"a":{"en":"No; state the equal corresponding angles and their transversal.","pt":"Não; declare os ângulos correspondentes iguais e sua transversal."}}],"observe":{"en":"Inspect copied radii and chord and ask the learner to identify the corresponding-angle pair.","pt":"Inspecione raios e corda copiados e peça que identifique os ângulos correspondentes."},"support":{"en":"Begin with angle copying alone; provide labelled arcs and choose between two candidate copies.","pt":"Comece só pela cópia do ângulo; forneça arcos identificados e escolha entre duas cópias candidatas."},"extend":{"en":"Explain the equality using three equal sides; distinguish copying from bisecting.","pt":"Explique a igualdade usando três lados iguais; distinga copiar de bissetar."},"links":["../lessons/G6-07.html","../lessons/G6-08.html"],"diagram":"parallel","duration":45,"jarman":"102–107"},{"id":"P6-02","grade":6,"title":{"en":"The path halfway between two lines","pt":"O caminho a meio entre duas retas"},"gap":{"en":"Adds the missing middle-parallel construction and its equal-distance condition.","pt":"Acrescenta a construção da paralela média e a condição de equidistância."},"source":"S79–80","ready":{"en":"Construct a midpoint and a parallel through a point.","pt":"Construir ponto médio e paralela por um ponto."},"materials":{"en":"Paper, straightedge, compass and set square for checking.","pt":"Papel, régua sem graduação, compasso e esquadro para conferir."},"aim":{"en":"Construct the unique line halfway between two distinct parallel lines; measure perpendicular distance.","pt":"Construir a reta única a meio entre duas paralelas distintas; medir distância perpendicular."},"teaching":{"en":"Intersect the parallel lines with any transversal at A and B. Construct midpoint M of AB. A parallel through M lies halfway between the originals, even if AB is slanted. Distance between parallel lines is measured perpendicularly; a slanted segment across the strip is longer than that distance.","pt":"Corte as paralelas com qualquer transversal em A e B. Construa o ponto médio M de AB. A paralela por M fica a meio entre as originais, mesmo com AB inclinado. A distância entre paralelas é medida perpendicularmente; um segmento inclinado atravessando a faixa é maior que essa distância."},"flow":[{"en":"5 min · Recall the difference between a midpoint and a perpendicular foot.","pt":"5 min · Retome a diferença entre ponto médio e pé de perpendicular."},{"en":"15 min · Draw two parallel lines and an oblique crossing segment AB. Construct M with equal-radius arcs. Construct a parallel through M using the preceding angle-transfer lesson.","pt":"15 min · Trace duas paralelas e um segmento transversal inclinado AB. Construa M com arcos iguais. Construa uma paralela por M usando a aula anterior de transferência de ângulo."},{"en":"20 min · Draw a second transversal elsewhere and find its midpoint N. Check that N lies on the constructed middle line. Use a perpendicular to compare the two strip widths.","pt":"20 min · Trace outra transversal e ache seu ponto médio N. Confira se N está na paralela média. Use uma perpendicular para comparar as larguras das duas faixas."},{"en":"5 min · Explain why a slanted crossing length is not the strip width; retrieve the construction next week.","pt":"5 min · Explique por que o comprimento inclinado não é a largura; retome a construção na próxima semana."}],"practice":[{"q":{"en":"Two parallel boundaries are 8 cm apart. How far is the middle parallel from each?","pt":"Duas paralelas estão separadas por 8 cm. A que distância fica a paralela média de cada uma?"},"a":{"en":"4 cm, measured perpendicularly.","pt":"4 cm, medidos perpendicularmente."}},{"q":{"en":"An oblique segment AB is 10 cm. What is AM?","pt":"Um segmento inclinado AB mede 10 cm. Quanto mede AM?"},"a":{"en":"5 cm along that transversal; this does not establish the perpendicular strip width.","pt":"5 cm nessa transversal; isso não determina a largura perpendicular da faixa."}},{"q":{"en":"Can the same construction define a constant-width middle strip for intersecting lines?","pt":"A mesma construção define faixa média de largura constante entre retas concorrentes?"},"a":{"en":"No; intersecting lines do not have constant separation. Their angle bisectors form a different equal-distance locus.","pt":"Não; concorrentes não têm separação constante. Suas bissetrizes formam outro lugar de equidistância."}}],"observe":{"en":"Check both the midpoint construction and the perpendicular-distance explanation.","pt":"Confira construção do ponto médio e explicação da distância perpendicular."},"support":{"en":"Start with a perpendicular transversal and prepared parallels, then try an oblique one.","pt":"Comece com transversal perpendicular e paralelas prontas; depois tente uma inclinada."},"extend":{"en":"Divide the strip into four equal-width bands by repeating the midpoint construction.","pt":"Divida a faixa em quatro larguras iguais repetindo a construção."},"links":["P5-01.html","P6-01.html"],"diagram":"parallel","duration":45,"jarman":"159"},{"id":"P7-01","grade":7,"title":{"en":"When a quadrilateral fits a circle","pt":"Quando um quadrilátero cabe numa circunferência"},"gap":{"en":"Adds the cyclic-quadrilateral extension anticipated in Schuberth’s Grade 4 discussion.","pt":"Acrescenta a extensão de quadriláteros cíclicos prevista na discussão do 4º ano de Schuberth."},"source":"S33","ready":{"en":"Optional Grade 7 extension; Jarman places the general circle-angle and cyclic-quadrilateral theorems in Grade 8. Begin with rectangles in Grade 7 and return after triangle-angle reasoning and circle-angle work.","pt":"Extensão opcional do 7º ano; Jarman situa teoremas gerais de ângulos na circunferência e quadriláteros cíclicos no 8º. Comece com retângulos no 7º e retome após raciocínio angular triangular e estudo angular da circunferência."},"materials":{"en":"Compass, straightedge, tracing paper and protractor.","pt":"Compasso, régua sem graduação, papel vegetal e transferidor."},"aim":{"en":"Construct a circle through three noncollinear points and test a fourth; explain opposite-angle sums.","pt":"Construir circunferência por três pontos não colineares e testar um quarto; explicar a soma de ângulos opostos."},"teaching":{"en":"A cyclic quadrilateral has all four vertices on one circle. Find the centre through perpendicular bisectors of AB and BC; their intersection is equally distant from A,B,C. A fourth point D need not lie on that circle. For a convex cyclic quadrilateral, opposite interior angles sum to 180°: each is half its intercepted arc, and those two arcs make 360°. The inscribed-angle fact follows by joining the centre to the angle’s endpoints and vertex, then using the resulting isosceles triangles and triangle-angle sums.","pt":"Um quadrilátero cíclico tem os quatro vértices na mesma circunferência. Ache o centro pelas mediatrizes de AB e BC; a interseção é equidistante de A,B,C. Um quarto ponto D pode não pertencer à circunferência. Num quadrilátero convexo cíclico, ângulos internos opostos somam 180°: cada um vale metade do arco que intercepta e esses arcos completam 360°. A relação do ângulo inscrito decorre de ligar o centro às extremidades e ao vértice do ângulo, usando os triângulos isósceles e a soma de ângulos."},"flow":[{"en":"5 min · Recall that a rectangle’s diagonals meet at equal distances from all four corners.","pt":"5 min · Retome que as diagonais de um retângulo se encontram a distâncias iguais dos quatro vértices."},{"en":"15 min · Mark noncollinear A,B,C and construct two perpendicular bisectors. Draw the circle through them. Choose D on the remaining arc to make a convex quadrilateral.","pt":"15 min · Marque A,B,C não colineares e construa duas mediatrizes. Trace a circunferência por eles. Escolha D no arco restante para fazer quadrilátero convexo."},{"en":"20 min · Measure opposite angles and record sums. Draw the two intercepted arcs in different colours. Explain the half-arc relation; move D off the circle and test again.","pt":"20 min · Meça ângulos opostos e registre somas. Destaque os dois arcos interceptados com cores diferentes. Explique a relação de meio arco; mova D para fora da circunferência e teste novamente."},{"en":"5 min · Separate measurement evidence from the general arc argument. Revisit the argument next week with a rotated figure.","pt":"5 min · Separe evidência medida do argumento geral dos arcos. Retome na próxima semana com figura girada."}],"practice":[{"q":{"en":"One opposite angle is 112°. Find the other for a convex cyclic quadrilateral.","pt":"Um ângulo oposto mede 112°. Ache o outro num quadrilátero convexo cíclico."},"a":{"en":"68°, because 180° − 112° = 68°.","pt":"68°, pois 180° − 112° = 68°."}},{"q":{"en":"Is every rectangle cyclic?","pt":"Todo retângulo é cíclico?"},"a":{"en":"Yes. Its diagonal intersection is equally far from all four vertices.","pt":"Sim. A interseção das diagonais é equidistante dos quatro vértices."}},{"q":{"en":"Can a nonsquare rhombus be cyclic?","pt":"Um losango não quadrado pode ser cíclico?"},"a":{"en":"No. Its opposite angles are equal; if supplementary, each would be 90°, making it a square.","pt":"Não. Seus ângulos opostos são iguais; se suplementares, cada um seria 90°, tornando-o quadrado."}}],"observe":{"en":"Check the fourth point rather than assuming every quadrilateral has a circumcircle. Accept arc reasoning only once its prerequisite is understood.","pt":"Confira o quarto ponto sem presumir circunferência para todo quadrilátero. Aceite o argumento dos arcos só quando o pré-requisito estiver compreendido."},"support":{"en":"Use a rectangle first; treat the general angle theorem as a teacher-guided extension if needed.","pt":"Comece com retângulo; trate o teorema angular geral como extensão orientada se necessário."},"extend":{"en":"Prove the inscribed-angle fact first when the centre lies on an angle ray, then split a general angle into those cases.","pt":"Demonstre primeiro a relação do ângulo inscrito com centro numa semirreta do ângulo; depois decomponha o caso geral."},"links":["P4-03.html","../lessons/G7-02.html","../lessons/G7-13.html"],"diagram":"cyclic","duration":45,"jarman":"158–159,198"},{"id":"P8-01","grade":8,"title":{"en":"A quadrilateral around a circle","pt":"Um quadrilátero ao redor de um círculo"},"gap":{"en":"Adds tangential quadrilaterals and a necessary length check, complementing cyclic figures.","pt":"Acrescenta quadriláteros tangenciais e uma condição necessária de comprimentos, complementando figuras cíclicas."},"source":"S33","ready":{"en":"Know perpendicular radius/tangent relationship and congruent right triangles; review with the teacher.","pt":"Conhecer a perpendicularidade entre raio e tangente e triângulos retângulos congruentes; revisar com docente."},"materials":{"en":"Compass, straightedge, set square, paper.","pt":"Compasso, régua sem graduação, esquadro, papel."},"aim":{"en":"Build a quadrilateral with an incircle and justify equal tangent lengths from each vertex.","pt":"Construir quadrilátero com círculo inscrito e justificar tangentes iguais de cada vértice."},"teaching":{"en":"A tangential quadrilateral has a circle touching all four sides. A tangent is perpendicular to the radius at contact. From an external vertex, the two tangent segments to the same circle have equal lengths: the right triangles share the centre-to-vertex hypotenuse and have equal radii. If vertex tangent lengths are x,y,z,w in order, the sides are x+y,y+z,z+w,w+x, so opposite side sums agree. Treat that equality as a necessary check; do not claim a measured equality alone proves an incircle.","pt":"Um quadrilátero tangencial tem um círculo tocando seus quatro lados. A tangente é perpendicular ao raio no contato. De um vértice externo, os dois segmentos tangentes à mesma circunferência são iguais: os triângulos retângulos têm hipotenusa comum do centro ao vértice e raios iguais. Se os comprimentos tangentes dos vértices são x,y,z,w em ordem, os lados são x+y,y+z,z+w,w+x, logo as somas dos lados opostos coincidem. Trate a igualdade como condição necessária; uma igualdade medida sozinha não demonstra círculo inscrito."},"flow":[{"en":"5 min · Distinguish vertices on a circle from sides touching a circle.","pt":"5 min · Distinga vértices na circunferência de lados tangenciando a circunferência."},{"en":"15 min · Draw a circle and four contact points around it, with no angular gap of 180° or more. At each contact construct a perpendicular to its radius. Adjacent tangents meet to enclose the circle; adjust contact choices if necessary.","pt":"15 min · Trace circunferência e quatro contatos ao redor, sem intervalo angular de 180° ou mais. Construa em cada contato uma perpendicular ao raio. Tangentes vizinhas se encontram cercando o círculo; ajuste os contatos se necessário."},{"en":"20 min · Label vertices A,B,C,D and contact points. Mark each pair of equal tangent segments and derive AB+CD=BC+DA before measuring.","pt":"20 min · Identifique vértices A,B,C,D e contatos. Marque pares de tangentes iguais e deduza AB+CD=BC+DA antes de medir."},{"en":"5 min · Explain the difference from a cyclic quadrilateral. Retrieve the tangent-pair reason next week.","pt":"5 min · Explique a diferença para um quadrilátero cíclico. Retome a razão das tangentes iguais na próxima semana."}],"practice":[{"q":{"en":"AB=7, BC=6 and CD=5 cm. Find DA if the quadrilateral is tangential.","pt":"AB=7, BC=6 e CD=5 cm. Ache DA se o quadrilátero é tangencial."},"a":{"en":"7 + 5 = 6 + DA, so DA = 6 cm.","pt":"7 + 5 = 6 + DA, portanto DA = 6 cm."}},{"q":{"en":"Can a 4 cm by 6 cm rectangle have a circle tangent to all four sides?","pt":"Um retângulo de 4 cm por 6 cm pode ter círculo tangente aos quatro lados?"},"a":{"en":"No. Opposite sums are 8 and 12 cm; a circle cannot have both diameters 4 and 6 cm.","pt":"Não. As somas opostas são 8 e 12 cm; um círculo não pode ter diâmetros de 4 e 6 cm."}},{"q":{"en":"A square has side 8 cm. Find its incircle radius.","pt":"Um quadrado tem lado 8 cm. Ache o raio do círculo inscrito."},"a":{"en":"4 cm, half the separation of opposite sides.","pt":"4 cm, metade da distância entre lados opostos."}}],"observe":{"en":"Require tangent contact, perpendicular radii and equal-length pairs in the explanation.","pt":"Exija contato tangente, raios perpendiculares e pares iguais na explicação."},"support":{"en":"Begin with a square and its incircle; use prepared tangent lines to compare a more general shape.","pt":"Comece com quadrado e círculo inscrito; use tangentes prontas para comparar forma mais geral."},"extend":{"en":"Compare a square, which is both cyclic and tangential, with a nonsquare rectangle, which is only cyclic.","pt":"Compare quadrado, que é cíclico e tangencial, com retângulo não quadrado, que é apenas cíclico."},"links":["P7-01.html","../lessons/G8-01.html"],"diagram":"tangent","duration":45,"jarman":"168,170"},{"id":"P8-02","grade":8,"title":{"en":"A room drawn toward a vanishing point","pt":"Um quarto desenhado para um ponto de fuga"},"gap":{"en":"Expands the existing brief perspective extension into a teachable project.","pt":"Amplia a breve extensão de perspectiva existente para um projeto de ensino."},"source":"J171–175,198","ready":{"en":"Distinguish a plan from a front view; recognise parallel lines and scale.","pt":"Distinguir planta de vista frontal; reconhecer paralelas e escala."},"materials":{"en":"Paper, pencil, straightedge and a simple box or room photograph.","pt":"Papel, lápis, régua sem graduação e uma caixa simples ou foto de quarto."},"aim":{"en":"Construct a one-point perspective interior and distinguish apparent convergence from physical parallelism.","pt":"Construir um interior em perspectiva de um ponto e distinguir convergência aparente de paralelismo físico."},"teaching":{"en":"In one-point perspective for a room viewed straight toward its back wall, horizontal and vertical edges of that wall stay horizontal and vertical in the picture. Edges perpendicular to that wall converge to one vanishing point on the horizon. Equal real depth intervals generally appear shorter farther away; equal paper spacing is not evidence of equal real depth. Perspective drawing is a projection, not a scale plan for measuring every length.","pt":"Na perspectiva de um ponto de um quarto visto de frente para a parede do fundo, as arestas horizontais e verticais dessa parede mantêm essas direções na imagem. Arestas perpendiculares a ela convergem a um ponto de fuga no horizonte. Intervalos reais iguais de profundidade geralmente parecem menores ao longe; espaçamento igual no papel não indica profundidade real igual. Perspectiva é projeção, não planta em escala para medir qualquer comprimento."},"flow":[{"en":"5 min · Compare the top-view reading-corner plan with a front view. Identify what each makes visible.","pt":"5 min · Compare a planta do canto de leitura com vista frontal. Identifique o que cada uma mostra."},{"en":"15 min · Draw a back-wall rectangle, a horizon through it and a vanishing point on that horizon. Extend rays from the vanishing point through the four corners to establish floor, ceiling and side walls.","pt":"15 min · Desenhe o retângulo da parede do fundo, horizonte por ele e ponto de fuga nesse horizonte. Prolongue semirretas do ponto de fuga pelos quatro vértices para estabelecer piso, teto e paredes laterais."},{"en":"20 min · Add a doorway on a side wall. Its vertical edges stay vertical and its receding top and bottom edges aim at the same vanishing point. Trace each line family in a different colour and compare with a box.","pt":"20 min · Acrescente uma porta na parede lateral. Suas arestas verticais ficam verticais e as bordas superior e inferior em profundidade apontam ao mesmo ponto de fuga. Destaque famílias de linhas com cores distintas e compare com uma caixa."},{"en":"5 min · Explain why real parallel edges can meet in the drawing. Next week, redraw with a higher horizon and compare eye level.","pt":"5 min · Explique por que arestas reais paralelas se encontram no desenho. Na próxima semana, redesenhe com horizonte mais alto e compare a altura do olhar."}],"practice":[{"q":{"en":"Should every edge in the picture aim at the vanishing point?","pt":"Toda aresta da imagem deve apontar ao ponto de fuga?"},"a":{"en":"No. Only the depth-direction family in this one-point setup; front-facing vertical and horizontal edges keep their directions.","pt":"Não. Apenas a família em profundidade nesse modelo; arestas frontais verticais e horizontais mantêm as direções."}},{"q":{"en":"Two floor tiles look different in depth. Must their real lengths differ?","pt":"Dois ladrilhos parecem diferentes em profundidade. Seus comprimentos reais precisam ser distintos?"},"a":{"en":"No. Projection makes equal lengths appear different at different distances.","pt":"Não. A projeção faz comprimentos iguais parecerem distintos a distâncias diferentes."}},{"q":{"en":"Which drawing should guide a measured floor layout: a declared-scale plan or this perspective sketch?","pt":"Qual desenho deve orientar um piso medido: planta com escala ou este esboço em perspectiva?"},"a":{"en":"The scale plan; perspective helps visualise space but has no single length scale throughout.","pt":"A planta em escala; a perspectiva ajuda a visualizar, mas não tem escala única de comprimento em toda parte."}}],"observe":{"en":"Check one common vanishing point for the depth edges and an explanation of what the drawing preserves.","pt":"Confira um ponto de fuga comum às arestas em profundidade e uma explicação do que o desenho preserva."},"support":{"en":"Provide the back wall, horizon and rays; let the learner identify line families aloud or by tracing.","pt":"Forneça parede, horizonte e semirretas; identifique famílias oralmente ou traçando."},"extend":{"en":"Move the vanishing point left or right on the horizon; compare the apparent room without claiming exact measurements.","pt":"Mova o ponto de fuga no horizonte; compare a aparência do quarto sem afirmar medidas exatas."},"links":["P3-01.html","../lessons/G8-12.html"],"diagram":"perspective","duration":45},{"id":"P4-05","grade":4,"title":{"en":"A compass rose by eye, then by comparison","pt":"Uma rosa dos ventos a olho e por comparação"},"gap":{"en":"Adds the freehand circle-division work explicitly proposed for Grade 4.","pt":"Acrescenta a divisão de círculos à mão livre proposta explicitamente para o 4º ano."},"source":"J73–75,195","ready":{"en":"Recognise halves, quarters and the four cardinal directions.","pt":"Reconhecer metades, quartos e os quatro pontos cardeais."},"materials":{"en":"Plain paper, soft and firm pencils, crayons; a prepared circle for support.","pt":"Papel liso, lápis macio e firme, giz de cera; círculo pronto para apoio."},"aim":{"en":"Sketch a circle and divide its boundary into 4, 8 and 16 approximately equal arcs; distinguish visual estimate from exact construction.","pt":"Esboçar círculo e dividir seu contorno em 4, 8 e 16 arcos aproximadamente iguais; distinguir estimativa visual de construção exata."},"teaching":{"en":"Begin with a light circular hand movement, then choose one clear outline. Two crossing diameters suggest four quarters. Halving each arc by eye gives eight parts, then sixteen. Joining each mark to the centre gives sectors, not equal-length straight boundary pieces. Freehand work trains judgment; it does not certify equality.","pt":"Comece com movimento circular leve e escolha um contorno claro. Dois diâmetros cruzados sugerem quatro quartos. Dividir cada arco a olho dá oito partes e depois dezesseis. Ligar marcas ao centro dá setores, não partes retas iguais no contorno. O desenho livre exercita o julgamento; não certifica igualdade."},"flow":[{"en":"5 min · Recall N, S, E and W; on this page choose north at the top and label the convention.","pt":"5 min · Retome N, S, L e O; nesta página escolha o norte em cima e declare essa convenção."},{"en":"15 min · Sketch a light circle freehand. Draw a clear outline, mark its estimated centre, and add vertical and horizontal diameters. Label the four directions.","pt":"15 min · Esboce círculo leve à mão livre. Destaque um contorno, estime o centro e acrescente diâmetros vertical e horizontal. Nomeie as direções."},{"en":"20 min · Estimate the midpoint of each quarter-arc; add NE, SE, SW, NW. Halve the arcs once more and colour alternate sectors. Compare with a folded circle; describe uneven gaps without erasing the evidence.","pt":"20 min · Estime o meio de cada quarto de arco; acrescente NE, SE, SO, NO. Divida os arcos mais uma vez e pinte setores alternados. Compare com círculo dobrado; descreva diferenças sem apagar as evidências."},{"en":"5 min · Explain what was estimated and what the fold checked. Repeat one quarter’s division from memory tomorrow.","pt":"5 min · Explique o que foi estimado e o que a dobra conferiu. Retome amanhã a divisão de um quarto."}],"practice":[{"q":{"en":"How many sectors result after halving each of 8 sectors?","pt":"Quantos setores resultam ao dividir cada um dos 8 ao meio?"},"a":{"en":"16; each old sector becomes two.","pt":"16; cada setor antigo vira dois."}},{"q":{"en":"What fraction of the circle is one of 16 equal sectors?","pt":"Qual fração do círculo é um de 16 setores iguais?"},"a":{"en":"1/16. Four such sectors make one quarter.","pt":"1/16. Quatro desses setores fazem um quarto."}},{"q":{"en":"Does drawing a neat circle prove all your arcs equal?","pt":"Desenhar círculo caprichado demonstra arcos iguais?"},"a":{"en":"No; a visual estimate needs a separate fold or later construction check.","pt":"Não; uma estimativa visual precisa de conferência por dobra ou construção posterior."}}],"observe":{"en":"Ask the learner to distinguish a direction label, a diameter and a sector, and to name one estimate.","pt":"Peça que distinga direção, diâmetro e setor e identifique uma estimativa."},"support":{"en":"Use a large prepared circle; work first with quarters and eighths.","pt":"Use círculo grande pronto; trabalhe primeiro quartos e oitavos."},"extend":{"en":"Later connect the 16 equal sectors with 360° ÷ 16 = 22.5°; formal degree work is optional here.","pt":"Depois relacione os 16 setores iguais a 360° ÷ 16 = 22,5°; graus formais são opcionais aqui."},"links":["P4-01.html","P5-02.html"],"diagram":"rose","duration":45},{"id":"P5-05","grade":5,"title":{"en":"A curve made from straight threads","pt":"Uma curva feita de fios retos"},"gap":{"en":"Adds simple line envelopes, absent from the existing Grade 5 bridge.","pt":"Acrescenta envoltórias simples de retas, ausentes da ponte existente do 5º ano."},"source":"J95,196","ready":{"en":"Mark equal intervals with a ruler and follow ordered pairs of marks.","pt":"Marcar intervalos iguais com régua e seguir pares ordenados de marcas."},"materials":{"en":"Paper, ruler, pencil and two coloured crayons.","pt":"Papel, régua, lápis e dois lápis de cor."},"aim":{"en":"Build an envelope from straight segments and distinguish the family of lines from the curve it suggests.","pt":"Construir envoltória de segmentos retos e distinguir a família de retas da curva sugerida."},"teaching":{"en":"Draw perpendicular rays from O. Mark 0 to 8 at equal intervals on each. Join horizontal mark i to vertical mark 8−i for i=0 to 8. Each thread is straight, but the family suggests a curved boundary. The boundary is an envelope, not one bent thread and not a curve made by simply joining the endpoints in order. Its mathematical continuation is parabolic; a few drawn segments only approximate it.","pt":"Trace semirretas perpendiculares de O. Marque 0 a 8 com intervalos iguais em cada uma. Una marca horizontal i à vertical 8−i, para i=0 a 8. Cada fio é reto, mas a família sugere contorno curvo. O contorno é envoltória, não fio curvado nem curva feita apenas unindo as extremidades em ordem. A continuação matemática é parabólica; poucos segmentos só a aproximam."},"flow":[{"en":"5 min · Recall that a ruler draws straight segments; predict whether many straight lines can suggest a curve.","pt":"5 min · Retome que a régua traça segmentos retos; preveja se muitos deles sugerem curva."},{"en":"15 min · Draw an 8 cm right angle and mark centimetres along both arms. Write pairs (0,8), (1,7), (2,6), through (8,0) before drawing.","pt":"15 min · Desenhe ângulo reto com braços de 8 cm e marque centímetros. Escreva os pares (0,8), (1,7), (2,6), até (8,0) antes de traçar."},{"en":"20 min · Join the paired marks. Trace a few segments in another colour and locate the curve they collectively suggest. Repeat with half-centimetre spacing, pairing marks whose distances sum to 8 cm.","pt":"20 min · Una as marcas em pares. Destaque alguns segmentos com outra cor e localize a curva sugerida pelo conjunto. Repita com espaçamento de meio centímetro, associando distâncias que somam 8 cm."},{"en":"5 min · Explain why this is an envelope rather than a single curved line. Recreate three pairs tomorrow.","pt":"5 min · Explique por que é envoltória e não uma linha curva única. Recrie três pares amanhã."}],"practice":[{"q":{"en":"Which vertical mark pairs with horizontal mark 3 cm?","pt":"Qual marca vertical corresponde à marca horizontal de 3 cm?"},"a":{"en":"5 cm, since 3 + 5 = 8.","pt":"5 cm, pois 3 + 5 = 8."}},{"q":{"en":"How many pairs are there with whole-centimetre marks from 0 through 8?","pt":"Quantos pares há com marcas de centímetros inteiros de 0 até 8?"},"a":{"en":"Nine, including both endpoints (0,8) and (8,0).","pt":"Nove, incluindo (0,8) e (8,0)."}},{"q":{"en":"Does reducing the spacing make any individual segment curved?","pt":"Reduzir o espaçamento torna algum segmento curvo?"},"a":{"en":"No; the denser family suggests the curved envelope more clearly.","pt":"Não; a família mais densa sugere melhor a envoltória curva."}}],"observe":{"en":"Look for correct pairing and an explanation of the distinction between segment and envelope.","pt":"Observe associação correta e explicação da diferença entre segmento e envoltória."},"support":{"en":"Provide numbered axes and a pair list; draw only every second segment first.","pt":"Forneça eixos numerados e lista de pares; trace primeiro um segmento a cada dois."},"extend":{"en":"In Grade 7, vary the angle or relative spacing and compare the envelopes; distinguish them from point loci in Grade 8.","pt":"No 7º ano, varie ângulo ou espaçamento e compare envoltórias; distinga-as dos lugares de pontos no 8º."},"links":["P4-05.html","P8-03.html"],"diagram":"envelope","duration":45},{"id":"P6-03","grade":6,"title":{"en":"Same triangle, or just the same area?","pt":"Mesmo triângulo ou apenas mesma área?"},"gap":{"en":"Makes congruence criteria an explicit bridge from construction to proof.","pt":"Torna critérios de congruência uma ponte explícita da construção à demonstração."},"source":"J102–107,197","ready":{"en":"Construct a triangle from three side lengths and recall perpendicular height.","pt":"Construir triângulo por três lados e retomar altura perpendicular."},"materials":{"en":"Compass, ruler, tracing paper and prepared triangles.","pt":"Compasso, régua, papel vegetal e triângulos prontos."},"aim":{"en":"Distinguish congruence from equal area; use SSS and SAS with their stated conditions.","pt":"Distinguir congruência de equivalência de área; usar LLL e LAL com condições declaradas."},"teaching":{"en":"Congruent triangles match exactly after moving or reflecting: all corresponding lengths and angles agree. Three side lengths determine a triangle up to congruence if they satisfy the triangle inequality (SSS). Two sides and the angle between them also determine it (SAS). Equal area alone does not. Two angles determine shape but allow different sizes.","pt":"Triângulos congruentes coincidem após movimento ou reflexão: comprimentos e ângulos correspondentes são iguais. Três lados determinam triângulo até congruência se satisfazem a desigualdade triangular (LLL). Dois lados e o ângulo entre eles também o determinam (LAL). Área igual sozinha não basta. Dois ângulos determinam forma, mas permitem tamanhos diferentes."},"flow":[{"en":"5 min · Compare two copies of one triangle in different orientations. Recall corresponding sides.","pt":"5 min · Compare cópias de um triângulo em orientações distintas. Retome lados correspondentes."},{"en":"15 min · Independently construct a 5–6–7 cm triangle twice. Draw a 7 cm base; intersect radius-5 and radius-6 arcs from its endpoints. Trace and overlay the two results, allowing a flip.","pt":"15 min · Construa duas vezes triângulo de 5–6–7 cm. Trace base de 7 cm; cruze arcos de raios 5 e 6 das extremidades. Trace e sobreponha os resultados, permitindo virar o papel."},{"en":"20 min · Draw right triangles with legs 4 and 6 cm, then 3 and 8 cm. Calculate their areas and compare longest sides. Construct another triangle from sides 5 and 6 cm with included angle 60°. Explain which information fixes each triangle.","pt":"20 min · Desenhe triângulos retângulos de catetos 4 e 6 cm e depois 3 e 8 cm. Calcule áreas e compare lados maiores. Construa outro por lados 5 e 6 cm e ângulo entre eles de 60°. Explique quais dados fixam cada um."},{"en":"5 min · State a valid congruence criterion and one insufficient condition; recall both next week.","pt":"5 min · Declare critério válido de congruência e condição insuficiente; retome ambos na próxima semana."}],"practice":[{"q":{"en":"Are the 4-by-6 and 3-by-8 right triangles equal in area?","pt":"Os triângulos retângulos de catetos 4 por 6 e 3 por 8 têm áreas iguais?"},"a":{"en":"Yes: each area is 12 cm². They are not congruent: their side lengths differ.","pt":"Sim: cada área é 12 cm². Não são congruentes: os lados diferem."}},{"q":{"en":"Can side lengths 2, 3 and 6 cm form a triangle?","pt":"Lados de 2, 3 e 6 cm formam triângulo?"},"a":{"en":"No, since 2 + 3 < 6; the arcs cannot form the required triangle.","pt":"Não, pois 2 + 3 < 6; os arcos não formam o triângulo exigido."}},{"q":{"en":"Two triangles both have angles 40°, 60°, 80°. Must they be congruent?","pt":"Dois triângulos têm ângulos de 40°, 60°, 80°. Precisam ser congruentes?"},"a":{"en":"No. They can have different sizes; matching angles establishes similarity, not congruence.","pt":"Não. Podem ter tamanhos distintos; ângulos iguais dão semelhança, não congruência."}}],"observe":{"en":"Ask for the matching parts and the criterion; reject an argument based only on appearance or area.","pt":"Peça partes correspondentes e critério; não aceite apenas aparência ou área."},"support":{"en":"Use prepared cut-outs and physical overlays before instrument work.","pt":"Use recortes prontos e sobreposição física antes dos instrumentos."},"extend":{"en":"Explore why two sides and an angle that is not between them can permit two triangles; do not call SSA a general congruence rule.","pt":"Explore por que dois lados e ângulo que não está entre eles podem permitir dois triângulos; não trate LLA como regra geral."},"links":["../lessons/G6-10.html","../lessons/G7-01.html"],"diagram":"congruence","duration":45},{"id":"P7-02","grade":7,"title":{"en":"Turn a quadrilateral into an equal-area triangle","pt":"Transforme quadrilátero em triângulo de mesma área"},"gap":{"en":"Adds the missing area-preserving polygon-to-triangle construction.","pt":"Acrescenta a construção de polígono para triângulo preservando área."},"source":"J151–152,197","ready":{"en":"Use area = base × perpendicular height ÷ 2 and construct parallels.","pt":"Usar área = base × altura perpendicular ÷ 2 e construir paralelas."},"materials":{"en":"Paper, straightedge, set square or compass and a centimetre grid.","pt":"Papel, régua sem graduação, esquadro ou compasso e grade centimetrada."},"aim":{"en":"Replace one triangle in a convex quadrilateral by an equal-area triangle to obtain a single triangle.","pt":"Substituir um triângulo de quadrilátero convexo por outro de mesma área para obter triângulo único."},"teaching":{"en":"For convex ABCD in boundary order, draw diagonal AC. Through B draw a parallel to AC meeting line AD at E (extend AD if needed). Triangles ABC and AEC share base AC and have equal perpendicular heights, so their areas agree. In the example below, E lies beyond A away from D, and combining AEC with ACD produces triangle ECD. The boundary lengths change; area is preserved. Check point order before combining regions in a different drawing.","pt":"Para ABCD convexo em ordem no contorno, trace diagonal AC. Por B, trace paralela a AC encontrando reta AD em E (prolongue se preciso). ABC e AEC têm base AC e alturas perpendiculares iguais, logo áreas iguais. No exemplo abaixo, E fica além de A, afastado de D, e juntar AEC com ACD produz ECD. O contorno muda; a área é preservada. Confira a ordem dos pontos antes de combinar regiões em outro desenho."},"flow":[{"en":"5 min · Recall why triangles on the same base between the same parallels have equal areas.","pt":"5 min · Retome por que triângulos na mesma base entre as mesmas paralelas têm áreas iguais."},{"en":"15 min · On a cm grid mark A=(0,0), B=(6,0), C=(4,3), D=(0,3). Draw ABCD and AC. Through B draw a parallel to AC until it meets the vertical line AD extended downward at E.","pt":"15 min · Em grade em cm, marque A=(0,0), B=(6,0), C=(4,3), D=(0,3). Trace ABCD e AC. Por B trace paralela a AC até encontrar AD prolongada para baixo em E."},{"en":"20 min · Compare triangles ABC and AEC by their common base AC and equal heights. Outline triangle ECD. Check both areas independently using the original trapezoid and the new triangle.","pt":"20 min · Compare ABC e AEC pela base comum AC e alturas iguais. Contorne ECD. Confira ambas as áreas pela do trapézio original e pela do novo triângulo."},{"en":"5 min · Explain the preserved quantity and why equal area does not imply congruence. Repeat the argument next week.","pt":"5 min · Explique a grandeza preservada e por que mesma área não implica congruência. Retome na próxima semana."}],"practice":[{"q":{"en":"Find the area of ABCD with parallel sides 6 and 4 cm and height 3 cm.","pt":"Ache a área de ABCD com lados paralelos de 6 e 4 cm e altura de 3 cm."},"a":{"en":"(6 + 4) × 3 ÷ 2 = 15 cm².","pt":"(6 + 4) × 3 ÷ 2 = 15 cm²."}},{"q":{"en":"E=(0,−4.5). Find the area of ECD.","pt":"E=(0,−4,5). Ache a área de ECD."},"a":{"en":"ED=7.5 cm and its perpendicular height from C is 4 cm: area = 7.5 × 4 ÷ 2 = 15 cm².","pt":"ED=7,5 cm e sua altura perpendicular desde C é 4 cm: área = 7,5 × 4 ÷ 2 = 15 cm²."}},{"q":{"en":"Did the perimeter have to stay the same?","pt":"O perímetro precisou permanecer igual?"},"a":{"en":"No. The equal-base-and-height argument preserves area, not perimeter.","pt":"Não. O argumento de base e altura iguais preserva área, não perímetro."}}],"observe":{"en":"Check the correct parallel, the shared base and the external height rather than a traced resemblance.","pt":"Confira paralela correta, base comum e altura externa, não semelhança de contorno."},"support":{"en":"Provide the grid and E; compare the two component triangles first.","pt":"Forneça grade e E; compare primeiro os dois triângulos componentes."},"extend":{"en":"Repeat the process to reduce a convex pentagon one vertex at a time; justify each area replacement.","pt":"Repita para reduzir pentágono convexo um vértice por vez; justifique cada substituição."},"links":["P6-03.html","../lessons/G7-06.html"],"diagram":"equal-area","duration":45},{"id":"P7-03","grade":7,"title":{"en":"A path receding toward the horizon","pt":"Um caminho que recua até o horizonte"},"gap":{"en":"Introduces freehand perspective in Grade 7 before the Grade 8 room project.","pt":"Introduz perspectiva à mão livre no 7º ano antes do projeto de quarto do 8º."},"source":"J171–173,197","ready":{"en":"Distinguish a front view and a plan; recognise a family of parallel edges.","pt":"Distinguir vista frontal e planta; reconhecer família de bordas paralelas."},"materials":{"en":"Paper, pencils and a picture of a straight path or corridor.","pt":"Papel, lápis e imagem de caminho reto ou corredor."},"aim":{"en":"Draw a simple one-point scene and explain foreshortening without treating the sketch as a scale plan.","pt":"Desenhar cena simples de um ponto e explicar encurtamento sem tratar esboço como planta em escala."},"teaching":{"en":"With a level view along a straight path, its parallel edges appear to meet at a vanishing point on the horizon. Equally tall posts appear shorter with distance. Vertical posts remain vertical in this model. Only lines in the same receding direction share that vanishing point; not all lines in a picture converge there.","pt":"Numa vista nivelada ao longo de caminho reto, suas bordas paralelas parecem encontrar-se no ponto de fuga no horizonte. Postes de mesma altura parecem menores à distância. Postes verticais continuam verticais nesse modelo. Só linhas na mesma direção de profundidade compartilham esse ponto; nem todas as linhas da imagem convergem ali."},"flow":[{"en":"5 min · Compare a top-view path with a photograph along it. Identify real parallel boundaries.","pt":"5 min · Compare planta de caminho com fotografia ao longo dele. Identifique bordas realmente paralelas."},{"en":"15 min · Draw a level horizon and choose V on it. Draw two path edges from the lower page toward V; add one near vertical post and its far partners, gradually shorter.","pt":"15 min · Trace horizonte nivelado e escolha V nele. Trace bordas do caminho desde a parte inferior até V; acrescente poste vertical próximo e outros mais distantes, gradualmente menores."},{"en":"20 min · Add the line through the post tops aiming toward V when their bases lie along the same straight level path. Turn the paper and compare; describe why that changes the apparent eye level. Add landscape freely without claiming exact spacing.","pt":"20 min · Acrescente linha pelos topos rumo a V quando as bases seguem o mesmo caminho reto e nivelado. Gire o papel e compare; descreva por que muda a altura aparente do olhar. Acrescente paisagem livremente sem afirmar espaçamentos exatos."},{"en":"5 min · Name what is physically parallel and what appears to converge. Next week, use the room project if ready.","pt":"5 min · Nomeie o que é fisicamente paralelo e o que parece convergir. Na próxima semana, use o projeto do quarto se houver prontidão."}],"practice":[{"q":{"en":"Are the real path edges meeting at the horizon?","pt":"As bordas reais do caminho se encontram no horizonte?"},"a":{"en":"No; their projected images converge. The real edges remain parallel.","pt":"Não; as imagens projetadas convergem. As bordas reais continuam paralelas."}},{"q":{"en":"Must farther equal-height posts be drawn taller?","pt":"Postes distantes de mesma altura devem ser desenhados maiores?"},"a":{"en":"No; in this level-view model they appear shorter with distance.","pt":"Não; nesse modelo nivelado parecem menores com a distância."}},{"q":{"en":"Does one vanishing point mean all picture lines go through it?","pt":"Um ponto de fuga significa que todas as linhas da imagem passam por ele?"},"a":{"en":"No. The vertical posts remain vertical, and front-facing horizontals stay horizontal.","pt":"Não. Postes verticais continuam verticais e horizontais frontais permanecem horizontais."}}],"observe":{"en":"Check that the learner describes apparent convergence without changing the real objects’ parallelism.","pt":"Confira descrição da convergência aparente sem alterar paralelismo real."},"support":{"en":"Provide a horizon and two receding edges; let the learner add or describe three posts.","pt":"Forneça horizonte e duas bordas; acrescente ou descreva três postes."},"extend":{"en":"Place V off-centre and redraw; explain the changed viewing direction.","pt":"Coloque V fora do centro e redesenhe; explique a mudança de direção do olhar."},"links":["P3-01.html","P8-02.html"],"diagram":"perspective","duration":45},{"id":"P8-03","grade":8,"title":{"en":"An ellipse keeps a sum unchanged","pt":"Uma elipse mantém uma soma constante"},"gap":{"en":"Extends the existing equal-distance locus lesson to a constant sum of two distances.","pt":"Amplia a aula de equidistância para soma constante de duas distâncias."},"source":"J157–160,198","ready":{"en":"Distinguish a circle’s centre and radius; measure two lengths in common units.","pt":"Distinguir centro e raio do círculo; medir dois comprimentos na mesma unidade."},"materials":{"en":"Paper, two fixed taped anchors, nonstretch thread, pencil and ruler; prepared points if needed.","pt":"Papel, duas âncoras fixas com fita, fio que não estica, lápis e régua; pontos prontos se necessário."},"aim":{"en":"Plot a two-focus locus, test a fixed distance sum and distinguish it from a circle.","pt":"Marcar lugar de dois focos, testar soma fixa e distinguir do círculo."},"teaching":{"en":"An ellipse is the locus of points P for which PA+PB equals a fixed total greater than AB. With A and B 6 cm apart, choose a 10 cm path from A to P to B. A thread of usable length 10 cm with ends fixed at A and B stays taut as the pencil moves. The sum is fixed although each distance can change. The endpoints on line AB are 2 cm beyond each focus, so the major axis is 10 cm. A freehand oval does not by itself establish this property.","pt":"Elipse é o lugar de pontos P com PA+PB igual a total fixo maior que AB. Com A e B separados por 6 cm, escolha caminho de 10 cm de A a P a B. Um fio de comprimento útil de 10 cm, com pontas em A e B, fica esticado ao mover o lápis. A soma é fixa, embora cada distância varie. As extremidades em AB ficam 2 cm além de cada foco, logo o eixo maior mede 10 cm. Um oval à mão livre não estabelece essa propriedade."},"flow":[{"en":"5 min · Recall the locus at a fixed distance from one point; predict the effect of two fixed points and a fixed sum.","pt":"5 min · Retome o lugar de distância fixa a um ponto; preveja efeito de dois pontos e soma fixa."},{"en":"15 min · Mark A and B 6 cm apart. An adult fixes thread ends to safe taped anchors, leaving 10 cm of usable thread between them. Use a pencil inside the slack and pull taut; trace without stretching.","pt":"15 min · Marque A e B separados por 6 cm. Um adulto fixa pontas do fio em âncoras seguras com fita, deixando 10 cm úteis. Coloque lápis na folga e estique; trace sem deformar o fio."},{"en":"20 min · Mark four points and measure PA, PB and their sum. Compare near an end and above the midpoint. Keep foci fixed and try a 12 cm thread; explain why the new ellipse is larger.","pt":"20 min · Marque quatro pontos e meça PA, PB e a soma. Compare perto de extremidade e acima do ponto médio. Mantenha focos e tente fio de 12 cm; explique por que a nova elipse é maior."},{"en":"5 min · State the locus condition and its units. Retrieve it next week without saying merely “an oval”.","pt":"5 min · Declare condição do lugar e unidades. Retome na próxima semana sem dizer só “um oval”."}],"practice":[{"q":{"en":"If PA is 3.5 cm and the sum is 10 cm, find PB.","pt":"Se PA mede 3,5 cm e a soma é 10 cm, ache PB."},"a":{"en":"PB=6.5 cm; 3.5+6.5=10.","pt":"PB=6,5 cm; 3,5+6,5=10."}},{"q":{"en":"Can a 5 cm total make an ellipse when AB is 6 cm?","pt":"Um total de 5 cm forma elipse com AB de 6 cm?"},"a":{"en":"No. PA+PB is at least AB by the triangle inequality. For a nondegenerate ellipse the total must exceed 6 cm.","pt":"Não. PA+PB é pelo menos AB pela desigualdade triangular. Para elipse não degenerada, o total deve superar 6 cm."}},{"q":{"en":"What happens if both foci coincide and the total is 10 cm?","pt":"O que ocorre se os focos coincidem e o total é 10 cm?"},"a":{"en":"The locus is a circle of radius 5 cm, since PA=PB.","pt":"O lugar é círculo de raio 5 cm, pois PA=PB."}}],"observe":{"en":"Ask what stayed constant, and distinguish the full path sum from either individual distance.","pt":"Pergunte o que permaneceu e distinga soma do caminho de cada distância individual."},"support":{"en":"Use premarked pairs of distances and classify points as on or off the locus; a partner can move the pencil.","pt":"Use pares de distâncias prontos e classifique pontos no lugar ou fora dele; outra pessoa pode mover o lápis."},"extend":{"en":"For foci 6 cm apart and sum 10 cm, use the right triangle at the top point to find a 4 cm semi-minor axis.","pt":"Para focos separados por 6 cm e soma 10 cm, use triângulo retângulo no ponto superior para achar semieixo menor de 4 cm."},"links":["../lessons/G6-02.html","P5-05.html","P8-07.html"],"diagram":"ellipse-locus","duration":45},{"id":"P8-04","grade":8,"title":{"en":"Four centres, four different questions","pt":"Quatro centros, quatro perguntas diferentes"},"gap":{"en":"Adds the triangle-centres strand explicitly listed for Grade 8.","pt":"Acrescenta o eixo de centros do triângulo listado explicitamente no 8º ano."},"source":"J167–170,198","ready":{"en":"Construct perpendicular bisectors, angle bisectors and perpendiculars; identify side midpoints.","pt":"Construir mediatrizes, bissetrizes e perpendiculares; identificar pontos médios."},"materials":{"en":"Three copies of a scalene triangle, tracing paper, compass and ruler; optional cardboard and a broad support.","pt":"Três cópias de triângulo escaleno, papel vegetal, compasso e régua; cartolina e apoio largo opcionais."},"aim":{"en":"Distinguish circumcentre O, incentre I, centroid G and orthocentre H by their defining constructions.","pt":"Distinguir circuncentro O, incentro I, baricentro G e ortocentro H por suas construções."},"teaching":{"en":"O lies on perpendicular bisectors and is equally far from the vertices: it centres the circumcircle. I is the intersection of internal angle bisectors and is equally far from the side lines: perpendicular distances give the incircle radius. G is the intersection of medians joining vertices to opposite side midpoints; it balances a uniform triangular lamina. H is the intersection of altitudes, the lines through vertices perpendicular to opposite sides. A median, angle bisector and altitude generally differ. These four points need not be the same.","pt":"O pertence às mediatrizes e é equidistante dos vértices: centra a circunferência circunscrita. I é encontro das bissetrizes internas e equidistante das retas dos lados: distâncias perpendiculares dão raio inscrito. G é encontro das medianas que unem vértices aos pontos médios opostos; equilibra lâmina triangular uniforme. H é encontro das alturas, retas pelos vértices perpendiculares aos lados opostos. Mediana, bissetriz e altura geralmente diferem. Os quatro pontos não precisam coincidir."},"flow":[{"en":"5 min · Ask whether “the centre of a triangle” has just one meaning. List equal-distance and balancing questions.","pt":"5 min · Pergunte se “o centro do triângulo” tem só um significado. Liste perguntas de equidistância e equilíbrio."},{"en":"15 min · On one scalene triangle construct two perpendicular bisectors to find O; check the third vertex’s distance. On another construct two internal angle bisectors to find I; drop a perpendicular to a side for the incircle radius.","pt":"15 min · Num triângulo escaleno construa duas mediatrizes para achar O; confira distância ao terceiro vértice. Em outro, construa duas bissetrizes internas para achar I; baixe perpendicular a um lado para raio inscrito."},{"en":"20 min · On a third copy draw two medians to find G, then two altitudes to find H. Overlay the copies. If using a uniform cardboard model, test balance on a broad blunt support, never a compass point. Split across sessions if needed.","pt":"20 min · Na terceira cópia trace duas medianas para achar G e duas alturas para achar H. Sobreponha cópias. Com cartolina uniforme, teste equilíbrio em apoio largo e sem ponta, nunca na ponta do compasso. Divida em sessões se preciso."},{"en":"5 min · Match each centre with its construction and role. Recall two tomorrow and the other two next week.","pt":"5 min · Associe cada centro à construção e função. Retome dois amanhã e os outros na próxima semana."}],"practice":[{"q":{"en":"Which centre is equally far from all three vertices?","pt":"Qual centro é equidistante dos três vértices?"},"a":{"en":"The circumcentre O, from perpendicular bisectors.","pt":"O circuncentro O, pelas mediatrizes."}},{"q":{"en":"In a right triangle, where are H and O?","pt":"Num triângulo retângulo, onde estão H e O?"},"a":{"en":"H is the right-angle vertex; O is the midpoint of the hypotenuse. They differ.","pt":"H é o vértice reto; O é o ponto médio da hipotenusa. São distintos."}},{"q":{"en":"A median has length 9 cm. G divides it 2:1 from the vertex. Find the two parts.","pt":"Uma mediana mede 9 cm. G a divide em 2:1 a partir do vértice. Ache as partes."},"a":{"en":"6 cm from vertex to G and 3 cm from G to the side midpoint.","pt":"6 cm do vértice a G e 3 cm de G ao ponto médio do lado."}}],"observe":{"en":"Ask which distance is equal and how it is measured; check side midpoints versus perpendicular feet.","pt":"Pergunte qual distância é igual e como medi-la; confira pontos médios versus pés de perpendiculares."},"support":{"en":"Study O and I first using prepared triangles; revisit G and H in a second session.","pt":"Estude O e I primeiro com triângulos prontos; retome G e H noutra sessão."},"extend":{"en":"Compare acute, right and obtuse triangles: O and H may be outside; I and G remain inside nondegenerate triangles.","pt":"Compare triângulos agudos, retângulos e obtusos: O e H podem ficar fora; I e G ficam dentro dos não degenerados."},"links":["P5-01.html","../lessons/G6-08.html","P8-03.html"],"diagram":"centres","duration":45},{"id":"P8-05","grade":8,"title":{"en":"One solid, three measured views","pt":"Um sólido, três vistas medidas"},"gap":{"en":"Adds explicit orthogonal views and separates them from cabinet and true perspective.","pt":"Acrescenta vistas ortogonais explícitas e distingue-as da representação cavaleira reduzida e da perspectiva real."},"source":"J131–132,160–164,169,198","ready":{"en":"Read a scale drawing; distinguish length, width and height.","pt":"Ler desenho em escala; distinguir comprimento, largura e altura."},"materials":{"en":"A small rectangular box, squared paper, ruler and optional linking cubes.","pt":"Caixa retangular pequena, papel quadriculado, régua e cubos de encaixe opcionais."},"aim":{"en":"Draw front, top and side views consistently; explain which dimensions each view preserves.","pt":"Desenhar vistas frontal, superior e lateral coerentes; explicar dimensões preservadas em cada vista."},"teaching":{"en":"An orthogonal view projects straight onto a plane with parallel perpendicular projectors. For a box 6 cm wide, 4 cm deep and 8 cm high, the front view is 6×8, top 6×4 and side 4×8 cm. These drawings can share one scale. In cabinet representation the front face is true to scale while drawn depth is shortened, often by half. In true perspective receding parallel edges may converge; it has no single length scale across the whole image.","pt":"Uma vista ortogonal projeta diretamente num plano por projetantes paralelas e perpendiculares. Para caixa de 6 cm de largura, 4 cm de profundidade e 8 cm de altura, frente é 6×8, topo 6×4 e lado 4×8 cm. As vistas podem compartilhar escala. Na representação cavaleira reduzida, a face frontal está em escala e a profundidade é encurtada, frequentemente à metade. Na perspectiva real, paralelas em profundidade podem convergir; não há escala única de comprimento em toda a imagem."},"flow":[{"en":"5 min · Recall the difference between a plan and a perspective scene. Label the box’s three dimensions.","pt":"5 min · Retome diferença entre planta e cena em perspectiva. Identifique as três dimensões da caixa."},{"en":"15 min · Draw front, top and right-side orthogonal views at 1:2 scale. Align shared widths or heights and label which side is the front.","pt":"15 min · Trace vistas frontal, superior e lateral direita na escala 1:2. Alinhe larguras ou alturas compartilhadas e indique a frente."},{"en":"20 min · Draw a cabinet sketch of the same box with the front at 1:2 scale and depth at half that drawing scale. Compare the apparent depth with the measured top view. Identify hidden edges using dashed lines.","pt":"20 min · Faça esboço cavaleiro reduzido da caixa, com frente em 1:2 e profundidade à metade dessa escala. Compare profundidade aparente com vista superior medida. Indique arestas ocultas com tracejados."},{"en":"5 min · Explain which view gives each dimension without foreshortening. Next week, reconstruct a box from three views.","pt":"5 min · Explique qual vista dá cada dimensão sem encurtamento. Na próxima semana, reconstrua caixa por três vistas."}],"practice":[{"q":{"en":"At 1:2 scale, what dimensions have the front and top views?","pt":"Em 1:2, quais são as dimensões da frente e do topo?"},"a":{"en":"Front 3×4 cm; top 3×2 cm. Each real length is divided by 2.","pt":"Frente 3×4 cm; topo 3×2 cm. Cada comprimento real é dividido por 2."}},{"q":{"en":"How long is the 4 cm depth drawn in the cabinet sketch described here?","pt":"Quanto mede a profundidade real de 4 cm no esboço cavaleiro reduzido descrito?"},"a":{"en":"1 cm: first 4÷2=2 cm for the general scale, then halve the drawn depth.","pt":"1 cm: primeiro 4÷2=2 cm na escala geral, depois metade da profundidade desenhada."}},{"q":{"en":"Can one front-view rectangle uniquely identify a solid?","pt":"Um retângulo frontal identifica um sólido de modo único?"},"a":{"en":"No. Boxes of different depths can have the same front view; more views or dimensions are needed.","pt":"Não. Caixas de profundidades diferentes têm a mesma frente; precisam-se de outras vistas ou medidas."}}],"observe":{"en":"Check consistent shared dimensions and ask whether a line is hidden, receding or projected.","pt":"Confira dimensões comuns coerentes e pergunte se a linha é oculta, em profundidade ou projetada."},"support":{"en":"Use a real box and prepared rectangles; rotate the model, not the page, to find each view.","pt":"Use caixa real e retângulos prontos; gire o modelo, não a página, para achar cada vista."},"extend":{"en":"Draw an octahedron aligned vertex-to-vertex with the viewing direction; compare the projected outline with its actual edges.","pt":"Desenhe octaedro alinhado vértice a vértice com a direção de observação; compare contorno projetado com arestas reais."},"links":["P3-01.html","P8-02.html","../lessons/G8-03.html"],"diagram":"views","duration":45},{"id":"P8-06","grade":8,"title":{"en":"A pointed solid holds one third","pt":"Um sólido pontudo contém um terço"},"gap":{"en":"Fills pyramid and cone volume teaching beyond the existing box and cylinder activities.","pt":"Completa volumes de pirâmide e cone além das atividades existentes de caixa e cilindro."},"source":"J132–134,198","ready":{"en":"Calculate base areas and prism/cylinder volumes; distinguish perpendicular height from slant height.","pt":"Calcular áreas de bases e volumes de prisma/cilindro; distinguir altura perpendicular de inclinada."},"materials":{"en":"Matching-base, matching-height cone and cylinder containers, dry rice and tray, or supplied measurements.","pt":"Recipientes de cone e cilindro com bases e alturas iguais, arroz seco e bandeja, ou medidas fornecidas."},"aim":{"en":"Use V=Bh/3 for pyramids and cones, preserving units and using perpendicular height.","pt":"Usar V=Bh/3 para pirâmides e cones, preservando unidades e usando altura perpendicular."},"teaching":{"en":"A prism or cylinder of base area B and perpendicular height h has volume Bh. A pyramid or cone with the same base area and height has one third that volume. Three congruent corner-apex square pyramids can partition a cube, giving one exact special model. A filling experiment supports the general relationship but is not its proof; the general formula is supplied here, with fuller justification through equal-height cross-sections left for later. Slant height does not replace perpendicular height.","pt":"Um prisma ou cilindro de área da base B e altura perpendicular h tem volume Bh. Pirâmide ou cone com mesma área de base e altura tem um terço desse volume. Três pirâmides quadradas congruentes com ápice num canto podem dividir um cubo, dando modelo especial exato. Experimento de enchimento apoia a relação geral, mas não a demonstra; a fórmula geral é fornecida aqui, ficando justificativa por seções na mesma altura para depois. Altura inclinada não substitui perpendicular."},"flow":[{"en":"5 min · Predict the number of cone fills needed for a matching cylinder. Check that radius and perpendicular height match.","pt":"5 min · Preveja quantos cones enchem cilindro correspondente. Confira raio e altura perpendicular iguais."},{"en":"15 min · Fill the cone with dry rice, level it and transfer into the cylinder three times over a tray. Record spills and packing differences. Without containers, compare supplied volumes for B=36 cm² and h=9 cm.","pt":"15 min · Encha cone de arroz seco, nivele e transfira ao cilindro três vezes numa bandeja. Registre derramamentos e diferenças de acomodação. Sem recipientes, compare volumes para B=36 cm² e h=9 cm."},{"en":"20 min · Calculate a square pyramid with base side 6 cm and height 9 cm. Then calculate a cone with radius 3 cm and height 10 cm. State what is observed and what uses the supplied general formula.","pt":"20 min · Calcule pirâmide quadrada com lado da base 6 cm e altura 9 cm. Depois calcule cone de raio 3 cm e altura 10 cm. Declare o que foi observado e o que usa a fórmula geral fornecida."},{"en":"5 min · Explain the factor one third and the correct height. Retrieve both formulas next week before calculating.","pt":"5 min · Explique fator um terço e altura correta. Retome ambas as fórmulas na próxima semana antes de calcular."}],"practice":[{"q":{"en":"Find the volume of the 6 cm square-base pyramid, height 9 cm.","pt":"Ache o volume da pirâmide de base quadrada de lado 6 cm e altura 9 cm."},"a":{"en":"6²×9÷3=108 cm³. The matching prism has volume 324 cm³.","pt":"6²×9÷3=108 cm³. O prisma correspondente tem 324 cm³."}},{"q":{"en":"Find the volume of the cone of radius 3 cm and height 10 cm.","pt":"Ache o volume do cone de raio 3 cm e altura 10 cm."},"a":{"en":"π×3²×10÷3=30π cm³, approximately 94.2 cm³ using π≈3.14.","pt":"π×3²×10÷3=30π cm³, aproximadamente 94,2 cm³ usando π≈3,14."}},{"q":{"en":"A pyramid has base area 24 cm² and volume 72 cm³. Find its height.","pt":"Uma pirâmide tem base de 24 cm² e volume de 72 cm³. Ache a altura."},"a":{"en":"h=3V/B=216/24=9 cm, measured perpendicularly to the base plane.","pt":"h=3V/B=216/24=9 cm, medidos perpendicularmente ao plano da base."}}],"observe":{"en":"Check base area versus base length, cubic units and perpendicular height; distinguish experiment from proof.","pt":"Confira área versus comprimento da base, unidades cúbicas e altura perpendicular; distinga experimento de demonstração."},"support":{"en":"Use a table of base area, height, prism volume and one-third volume before circular bases.","pt":"Use tabela de área da base, altura, volume do prisma e seu terço antes de bases circulares."},"extend":{"en":"Double every length of the cone: volume becomes eight times as large, not twice or three times.","pt":"Dobre todos os comprimentos do cone: o volume fica oito vezes maior, não duas nem três."},"links":["../lessons/G8-06.html","../lessons/G8-08.html"],"diagram":"volume","duration":45},{"id":"P8-07","grade":8,"title":{"en":"The sliding strip and its moving midpoint","pt":"A tira deslizante e seu ponto médio móvel"},"gap":{"en":"Adds a moving-point locus and explicitly contrasts it with a family-of-lines envelope.","pt":"Acrescenta lugar de ponto móvel e contrasta explicitamente com envoltória de família de retas."},"source":"J157–160","ready":{"en":"Use a right angle, midpoint and the Pythagorean theorem.","pt":"Usar ângulo reto, ponto médio e teorema de Pitágoras."},"materials":{"en":"A 10 cm card strip, two perpendicular guides, paper, ruler and compass.","pt":"Tira de cartolina de 10 cm, duas guias perpendiculares, papel, régua e compasso."},"aim":{"en":"Trace a strip midpoint as its ends slide on perpendicular axes; explain its quarter-circle locus.","pt":"Traçar ponto médio de tira com pontas deslizando em eixos perpendiculares; explicar seu lugar em quarto de círculo."},"teaching":{"en":"Use a tabletop model, never a real ladder. A rigid strip has endpoints A=(x,0), B=(0,y), with x,y≥0 and x²+y²=100. Its midpoint M=(x/2,y/2) satisfies OM²=(x²+y²)/4=25, so M stays 5 cm from O. As both ends slide between the limiting positions, M traces a quarter-circle. The family of strip positions suggests a different envelope; do not substitute that boundary for the midpoint’s locus.","pt":"Use modelo de mesa, nunca escada real. Tira rígida tem pontas A=(x,0), B=(0,y), com x,y≥0 e x²+y²=100. Seu ponto médio M=(x/2,y/2) satisfaz OM²=(x²+y²)/4=25, logo fica a 5 cm de O. Entre posições limites, M traça quarto de círculo. A família das posições da tira sugere outra envoltória; não substitua o lugar do ponto médio por esse contorno."},"flow":[{"en":"5 min · Recall the difference between marking successive points and drawing many straight threads. Predict the midpoint path.","pt":"5 min · Retome diferença entre marcar pontos sucessivos e traçar muitos fios retos. Preveja caminho do ponto médio."},{"en":"15 min · Mark the strip midpoint at 5 cm. Slide its two ends along the perpendicular guides, keeping both in contact, and record six midpoint positions.","pt":"15 min · Marque ponto médio da tira em 5 cm. Deslize pontas pelas guias perpendiculares, ambas em contato, e registre seis posições do ponto médio."},{"en":"20 min · Measure each midpoint’s distance from guide intersection O. Check the 6–8–10 position, then justify all positions with the midpoint coordinates and Pythagoras. Compare a compass quarter-circle of radius 5 cm.","pt":"20 min · Meça distância de cada ponto médio à interseção O. Confira posição 6–8–10 e justifique todas por coordenadas do ponto médio e Pitágoras. Compare com quarto de círculo de raio 5 cm."},{"en":"5 min · Explain why points trace a circle although the strip rotates and slides. Retrieve the unchanged distance next week.","pt":"5 min · Explique por que pontos traçam círculo enquanto tira gira e desliza. Retome a distância constante na próxima semana."}],"practice":[{"q":{"en":"At A=(8,0), B=(0,6), where is M?","pt":"Com A=(8,0), B=(0,6), onde fica M?"},"a":{"en":"M=(4,3), so OM=√(4²+3²)=5 cm.","pt":"M=(4,3), logo OM=√(4²+3²)=5 cm."}},{"q":{"en":"If the strip is 14 cm long, what is the midpoint-locus radius?","pt":"Se a tira mede 14 cm, qual raio tem o lugar do ponto médio?"},"a":{"en":"7 cm, half the strip length.","pt":"7 cm, metade do comprimento da tira."}},{"q":{"en":"Do six measured points prove the complete locus?","pt":"Seis pontos medidos demonstram o lugar completo?"},"a":{"en":"No. They support a conjecture; the constant-distance argument justifies every permitted position.","pt":"Não. Apoiam uma conjectura; o argumento de distância constante justifica toda posição permitida."}}],"observe":{"en":"Look for a constant-distance argument and clear identification of the point being traced.","pt":"Observe argumento de distância constante e identificação clara do ponto traçado."},"support":{"en":"Use the 6–8–10 position and limiting horizontal/vertical positions before variable coordinates.","pt":"Use posição 6–8–10 e posições limites horizontal/vertical antes de coordenadas variáveis."},"extend":{"en":"A point a quarter of the way from A to B traces a quarter-ellipse; compare with the midpoint without assuming all strip points follow circles.","pt":"Um ponto a um quarto do caminho de A a B traça quarto de elipse; compare com ponto médio sem supor círculos para todos os pontos."},"links":["P5-05.html","P8-03.html","../lessons/G7-10.html"],"diagram":"ladder","duration":45}];
